/* global z, toastr */

const WORLD_KEYS = ['未选择', '异能都市', '古代修仙', '西幻', '跨世界'];
const STAGES = ['泥像期', '石像期', '铜像期', '银像期', '金像期', '玉像期', '宇宙神像期'];
const FAITH_LEVELS = ['普通', '核心', '狂热'];
const TASK_STATES = ['未发布', '进行中', '待验收', '已完成', '已失败', '已替代'];
const TRUTH_STAGES = ['毫无察觉', '隐约熟悉', '主动追索', '确认自身', '创世归位'];

const looseObject = shape => z.object(shape).passthrough();
const objectValue = shape => z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) ? value : {},
  looseObject(shape),
);
const recordValue = (valueSchema, fallback = {}) => z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) ? value : fallback,
  z.record(z.string(), valueSchema),
);
const arrayValue = (valueSchema, fallback = []) => z.preprocess(
  value => Array.isArray(value) ? value : fallback,
  valueSchema,
);
const stringValue = fallback => z.preprocess(
  value => value === undefined || value === null ? fallback : String(value),
  z.string(),
);
const numberValue = fallback => z.preprocess(
  value => value === undefined || value === null || value === '' ? fallback : value,
  z.coerce.number().int().min(0),
);
const boolValue = fallback => z.preprocess(
  value => value === undefined || value === null ? fallback
    : value === 'false' || value === 0 ? false
      : value === 'true' || value === 1 ? true : value,
  z.boolean(),
);
const enumValue = (values, fallback) => z.preprocess(
  value => values.includes(value) ? value : fallback,
  z.enum(values),
);
// 0.23.0：模型多写几个字、多塞几项、把半径写成天文数字，都不该让整楼变量更新报错。
// 一律在 preprocess 阶段截断/钳位，Schema 本身仍然保持严格形状。
const clipOpt = maxLen => z.preprocess(
  value => value === null || value === undefined || value === '' ? undefined : String(value).trim().slice(0, maxLen),
  z.string().max(maxLen).optional(),
);
const clipReq = (maxLen, fallback = 'auto-id') => z.preprocess(
  value => {
    const str = String(value ?? '').trim().slice(0, maxLen);
    return str || fallback;
  },
  z.string().min(1).max(maxLen),
);
const clampIntOpt = (minVal, maxVal) => z.preprocess(
  value => {
    if (value === null || value === undefined || value === '') return undefined;
    const num = Math.trunc(Number(value));
    if (!Number.isFinite(num)) return undefined;
    return Math.max(minVal, Math.min(maxVal, num));
  },
  z.number().int().min(minVal).max(maxVal).optional(),
);
const cappedArray = (itemSchema, maxItems) => z.preprocess(
  value => Array.isArray(value) ? value.slice(0, maxItems) : [],
  z.array(itemSchema).max(maxItems).default([]),
);

// 供奉：价格由脚本查表算，Schema 只保证结构完整。品类和成色的白名单在脚本里核对，
// 这样 AI 写错一个品类只丢这一条事件，不会让整楼的状态更新失败。
const OFFER_CATS = ['心意', '香烛', '食供', '布帛', '银钱', '金器', '玉石', '奇珍'];
const OFFER_GRADES = ['粗劣', '寻常', '上品', '稀世'];
const countValue = (fallback, max) => z.preprocess(value => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(max, Math.max(0, Math.trunc(number))) : fallback;
}, z.number().int().min(0).max(max));
const OfferItemSchema = objectValue({
  名称: stringValue(''),
  品类: stringValue(''),
  成色: stringValue(''),
  份数: countValue(1, 99),
});
// 待演晋升：脚本写入，AI 只读。渲染时当空对象或 null 都接受。
const PendingPromotionSchema = z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length ? value : null,
  looseObject({
    从: stringValue(''),
    到: stringValue(''),
    楼层: z.coerce.number().int().default(0),
    新权能: cappedArray(z.string(), 8),
    新半径: numberValue(0),
    新神力半径: numberValue(0),
    新神力范围: stringValue(''),
  }).nullable(),
);

const TaskSchema = z.preprocess(value => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const { 限期分钟, 期限说明, 失败处罚, ...active } = value;
  return active;
}, objectValue({
  id: stringValue(''),
  标题: stringValue(''),
  目标: stringValue(''),
  完成条件: stringValue(''),
  阶段目标: stringValue(''),
  进度当前: numberValue(0),
  进度目标: numberValue(0),
  奖励神力: numberValue(0),
  奖励说明: stringValue(''),
  奖励记忆碎片: stringValue(''),
  状态: enumValue(TASK_STATES, '未发布'),
}));

const WorldStateSchema = objectValue({
  地区声望: stringValue('无名'),
  稳定祭祀点: numberValue(0),
  公开神迹: numberValue(0),
  主要势力关系: recordValue(z.string()),
  首章状态: stringValue('未开始'),
});

const PrivateProfileSchema = objectValue({
  乳房: stringValue('未记录'),
  小穴: stringValue('未记录'),
  后穴: stringValue('未记录'),
});

// 信仰度、当前权能、私密状态只属于已经升到对应等级的人。这里绝不能用 objectValue / arrayValue /
// numberValue 做默认值：它们会把 undefined 补成 {} / [] / 0，于是每个路人都会长出这三个字段。
const GrantedPowerSchema = z.object({
  id: z.string().max(40),
  名称: z.string().max(20),
  效果: z.string().max(200),
  剩余: z.coerce.number().int().min(0).max(99),
  常驻: z.boolean(),
  赐予日: z.coerce.number().int().min(0),
}).passthrough();
// 隐秘档案：玩家在人物详情里手动生成，由 HUD 与脚本写；AI 的变量补丁写不进来，也不进资料版本。
const SecretDossierSchema = z.object({
  已生成: boolValue(false),
  已鉴赏: boolValue(false),
  更新时间: stringValue(''),
  亲密关系: stringValue(''),
  口腔: stringValue(''),
  乳房: stringValue(''),
  小穴评级: stringValue(''),
  小穴描述: stringValue(''),
  小穴特质: stringValue(''),
  后穴: stringValue(''),
  秘密: stringValue(''),
}).passthrough();
const DevotionFields = {
  信仰度: z.preprocess(v => v == null || v === '' ? undefined : v, z.coerce.number().int().min(0).max(100).optional()),
  好感度: z.preprocess(v => v == null || v === '' ? undefined : v, z.coerce.number().int().min(0).max(100).optional()),
  堕落值: z.preprocess(v => v == null || v === '' ? undefined : v, z.coerce.number().int().min(0).max(100).optional()),
  当前权能: z.preprocess(v => Array.isArray(v) ? v.slice(0, 8) : undefined, z.array(GrantedPowerSchema).max(8).optional()),
  私密状态: z.preprocess(v => v && typeof v === 'object' && !Array.isArray(v) ? v : undefined,
    z.object({ 身体: stringValue(''), 欲念: stringValue(''), 秘密: stringValue('') }).passthrough().optional()),
  隐秘档案: z.preprocess(v => v && typeof v === 'object' && !Array.isArray(v) ? v : undefined, SecretDossierSchema.optional()),
};

const LegacyImportantPersonSchema = objectValue({
  所属群体ID:stringValue(''),群体序号:z.number().int().min(0).optional(),
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  身份: stringValue(''),
  信仰等级: enumValue(['未确认','未信仰',...FAITH_LEVELS], '未确认'),
  关系: z.preprocess(value => value == null ? '' : value, z.union([z.string(), z.record(z.string(), z.unknown())])),
  所在位置: stringValue(''),
  当前状态: stringValue(''),
  当前服装: stringValue(''),
  当前心理: stringValue(''),
  当前姿势: stringValue(''),
  情绪: stringValue(''),
  外貌: stringValue(''),
  能力: arrayValue(z.array(z.string())),
  成长: objectValue({位阶:stringValue('未确认'),形态:stringValue('未进化'),神赐经历:arrayValue(z.array(z.string()).max(8))}),
  祈愿: objectValue({内容:stringValue(''),轮次:numberValue(0)}),
  与神关系: stringValue(''),
  近期经历: stringValue(''),
  最后更新: stringValue(''),
  别称: arrayValue(z.array(z.string()).max(8)),
  情感关系: objectValue({亲近阶段:enumValue(['未确认','初识','熟悉','倾慕','亲密','伴侣'],'未确认'),公开身份:stringValue('未确认'),当前在意:stringValue('未确认'),关键事实:arrayValue(z.array(objectValue({摘要:stringValue(''),来源楼层:numberValue(0),来源swipe:numberValue(0)})).max(8))}),
  私密档案: PrivateProfileSchema.optional(),
  ...DevotionFields,
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '重要人物必须年满 18 岁',
    });
  }
});

const ImportantPersonSchema = z.union([
  looseObject({姓名:stringValue(''),所属群体ID:stringValue(''),群体序号:z.number().int().min(0).optional(),信仰等级:enumValue(['未确认','未信仰',...FAITH_LEVELS],'未信仰'),档案版本:z.string().min(1),当前服装:stringValue(''),当前心理:stringValue(''),当前姿势:stringValue(''),当前状态:stringValue(''),情绪:stringValue(''),当前意图:stringValue(''),临时态度:stringValue(''),临时效果:cappedArray(z.string(), 12),祈愿:objectValue({内容:stringValue(''),轮次:numberValue(0)}),...DevotionFields}),
  LegacyImportantPersonSchema,
]);

const OrdinaryFollowerSchema = objectValue({
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  身份: stringValue(''),
  所在地: stringValue(''),
  首次见证: stringValue(''),
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '普通信徒必须年满 18 岁',
    });
  }
});

const CurrentVisitorSchema = objectValue({
  姓名: stringValue(''),
  年龄: numberValue(18),
  性别: stringValue(''),
  自定义描述: stringValue(''),
  身份: stringValue(''),
  状态: stringValue(''),
  所在地: stringValue(''),
}).superRefine((person, context) => {
  if (person.年龄 < 18) {
    context.addIssue({
      code: 'custom',
      path: ['年龄'],
      message: '当前来客必须年满 18 岁',
    });
  }
});

const BuildingSchema = objectValue({
  名称: stringValue(''), 类型: stringValue('房屋'),
  状态: enumValue(['规划','建造中','已完成','损毁'],'规划'),
  // 0.22.0 起建筑不再要求相对神像的坐标；旧档里的 x/y 继续读得出来，新回合不写就按 0 补齐。
  x: z.preprocess(v => v == null || v === '' ? 0 : v, z.coerce.number().finite().default(0)), y: z.preprocess(v => v == null || v === '' ? 0 : v, z.coerce.number().finite().default(0)),
  容量: numberValue(0), 安全: boolValue(false), 建造者: arrayValue(z.array(z.string())),
  住户: arrayValue(z.array(z.string())), 说明: stringValue(''),
}).superRefine((b,ctx) => {
  if (b.住户.length > b.容量 || b.住户.length && (b.状态 !== '已完成' || !b.安全) || new Set(b.住户).size !== b.住户.length) ctx.addIssue({code:'custom',path:['住户'],message:'住户须唯一，且建筑完工、安全、容量足够'});
});
const DomainSchema = objectValue({
  建筑: recordValue(BuildingSchema),
  已知地点: cappedArray(z.string(), 30),
}).superRefine((domain,ctx) => {
  const residents=new Set();
  for (const [id,b] of Object.entries(domain.建筑)) for (const key of b.住户) {
    if (residents.has(key)) ctx.addIssue({code:'custom',path:['建筑',id,'住户'],message:'同一住户不能同时入住两栋建筑'});
    residents.add(key);
  }
});
const ClockSchema=objectValue({
  起始时刻:stringValue('0102-09-16 17:40'),经过分钟:numberValue(0),已初始化:boolValue(false),
  已结算日:numberValue(0),累计香火:numberValue(0),最近批次:stringValue(''),
  结算记录:arrayValue(z.array(objectValue({截止日期:stringValue(''),天数:numberValue(0),日收益:numberValue(0),总额:numberValue(0)})).max(8)),
});
const PositionSchema=objectValue({地点ID:stringValue(''),x:z.coerce.number().finite().default(0),y:z.coerce.number().finite().default(0),有效:boolValue(false)});
const IntegerSchema=z.number().int().min(0).max(Number.MAX_SAFE_INTEGER);
const EconomicSchema=objectValue({
  已初始化:boolValue(false),规则版本:numberValue(1),启用楼层:numberValue(0),基准余额:numberValue(0),累计收入:numberValue(0),累计支出:numberValue(0),
  收入分类:objectValue({每日:numberValue(0),跪拜:numberValue(0),任务:numberValue(0),供奉:numberValue(0)}),
  支出分类:objectValue({晋升:numberValue(0),商城:numberValue(0),权能:numberValue(0)}),
  流水:arrayValue(z.array(objectValue({id:stringValue(''),日期:stringValue(''),类别:stringValue(''),变化:z.number().int().safe().default(0),余额:numberValue(0)})).max(64)),
  事件回执:arrayValue(z.array(objectValue({id:stringValue(''),内容:stringValue(''),结果:stringValue('')})).max(256)),
  日结日:numberValue(0),日结世界:stringValue('未选择'),跪拜日期:stringValue(''),
  供奉日期:stringValue(''),今日供奉:numberValue(0),
  供奉记录:arrayValue(z.array(objectValue({日期:stringValue(''),人物:stringValue(''),供品摘要:stringValue(''),积分:numberValue(0),所求:stringValue('')})).max(20)),
  跪拜人物:recordValue(z.boolean()),跪拜群体:recordValue(z.string().regex(/^[0-9a-f]*$/).max(250000)),
  访客:recordValue(objectValue({姓名:stringValue(''),信仰等级:enumValue(['未信仰'],'未信仰')})),
  旧自定义权能:arrayValue(z.array(z.string()).max(100)),
});
const EVENT_TYPES = ["跪拜","用能","任务完成","结束附身","上架","判定","供奉","信仰","好感","堕落","觉醒","信徒用能","获得"];
const SystemEventSchema=z.preprocess(
  value => value && typeof value === 'object' && !Array.isArray(value) ? value : {},
  looseObject({
    事件ID:clipReq(80,'auto-event'),
    类型:z.preprocess(v => EVENT_TYPES.includes(String(v ?? '').trim()) ? String(v).trim() : '判定', z.enum(EVENT_TYPES)),
    人物ID:clipOpt(120),姓名:clipOpt(80),群体ID:clipOpt(120),
    作用半径:clampIntOpt(1,50000000),持续分钟:clampIntOpt(1,10080),已确认代价:z.coerce.boolean().optional(),
    起始序号:z.coerce.number().int().min(0).optional(),人数:z.coerce.number().int().min(0).max(1000000).optional(),
    能力ID:clipOpt(80),任务ID:clipOpt(120),
    领域内:z.coerce.boolean().optional(),已建立联系:z.coerce.boolean().optional(),明确同意:z.coerce.boolean().optional(),
    事由:clipOpt(120),程度:clipOpt(20),权能ID:clipOpt(40),
    名称:clipOpt(60),说明:clipOpt(200),数量:clampIntOpt(1,999),来自:clipOpt(60),
    供品:cappedArray(OfferItemSchema,8).optional(),
    所求:clipOpt(120),
    类别:clipOpt(30),难度:clipOpt(20),礼物:clipOpt(60),商品ID:clipOpt(80),效果:clipOpt(300),处境:clipOpt(100),权能:clipOpt(40),对象:clipOpt(80),
  }).passthrough(),
);
const Schema = z.preprocess(root => {
  if (!root || typeof root !== 'object' || Array.isArray(root)) {
    return {};
  }
  return root;
}, looseObject({
  元数据: objectValue({
    schema版本: stringValue('2.0.0'),
    卡片版本: stringValue('0.16.1'),
    开局完成: boolValue(false),
    当前开局: stringValue('未选择'),
    最近更新说明: stringValue(''),
  }),
  世界: objectValue({
    当前世界: enumValue(WORLD_KEYS, '未选择'),
    已解锁世界: arrayValue(z.array(z.enum(WORLD_KEYS)).max(3)),
    当前区域: stringValue(''),
    当前地点: stringValue(''),
    剧情时间: stringValue('未开始'),
    世界状态: recordValue(WorldStateSchema),
  }),
  系统: objectValue({
    人格: stringValue('可靠执事'),
    当前提示: stringValue('等待开局选择系统人格。'),
  }),
  神格: objectValue({
    神名: stringValue(''),
    神格性别: stringValue(''),
    生前姓名: stringValue(''),
    外貌: stringValue(''),
    生前背景: stringValue(''),
    神像阶段: enumValue(STAGES, '泥像期'),
    绝对领域: objectValue({
      中心: stringValue('初始神像所在处'),
      // 内圈：绝对无敌领域半径（10 / 50 / 100 / 1000 / 5000 / 50000 米）。
      半径: numberValue(10),
      // 外圈：神力领域半径（100 / 500 / 1000 / 10000 / 500000 / 50000000 米）。
      神力半径: numberValue(100),
      神力范围: stringValue('100米'),
    }),
    神力积分: numberValue(3),
    化身: objectValue({
      可凝聚: boolValue(false),
      状态: stringValue('无实体'),
      所在地: stringValue('神像内'),
    }),
    附身: objectValue({
      进行中: boolValue(false),
      信徒键: stringValue(''),
      开始分钟: numberValue(0),
    }),
    已解锁能力: arrayValue(z.array(z.string()), ['神谕传音', '方寸异象']),
    待演晋升: PendingPromotionSchema,
  }),
  信仰: objectValue({
    普通信徒: numberValue(0),
    核心信徒: numberValue(0),
    狂热信徒: numberValue(0),
    上次结算天数: numberValue(1),
    累计公开神迹: numberValue(0),
  }),
  任务: objectValue({
    当前主线: TaskSchema,
    支线: cappedArray(TaskSchema, 3),
    最近完成: stringValue(''),
    历史:arrayValue(z.array(TaskSchema).max(64)),结算标记:recordValue(IntegerSchema),阶段完成:recordValue(z.boolean()),序列:numberValue(0),入门回应完成:boolValue(false),
    支线节奏:objectValue({上次发布楼层:z.coerce.number().int().default(-99),未出轮数:numberValue(0),上次完成楼层:z.coerce.number().int().default(-99)}),
    支线种子:arrayValue(z.array(objectValue({来源人物:stringValue(''),所求:stringValue(''),建议奖励:numberValue(0),来源楼层:z.coerce.number().int().default(0)})).max(5)),
  }),
  经济:EconomicSchema,
  商城:objectValue({永久权能:recordValue(IntegerSchema),限时权能:recordValue(objectValue({获得分钟:numberValue(0),到期分钟:numberValue(0),购买价格:numberValue(0)})),背包:recordValue(objectValue({名称:stringValue(''),说明:stringValue(''),效果:stringValue(''),类别:stringValue('物品'),来源:stringValue('商城'),来自:stringValue(''),权能:stringValue(''),判定加成:numberValue(0),数量:numberValue(1),演化分钟:numberValue(0),对象类型:stringValue('other')})),待生效:arrayValue(z.array(objectValue({实例:stringValue(''),楼层:numberValue(0),货号:stringValue(''),名称:stringValue(''),说明:stringValue(''),效果:stringValue(''),类别:stringValue('物品'),来源:stringValue('商城'),来自:stringValue(''),权能:stringValue(''),判定加成:numberValue(0),对象:stringValue(''),演化分钟:numberValue(0)})).max(24)),演化:recordValue(objectValue({名称:stringValue(''),对象:stringValue(''),开始分钟:numberValue(0),到期分钟:numberValue(0)})),定制货架:cappedArray(objectValue({id:stringValue(''),名称:stringValue(''),说明:stringValue(''),效果:stringValue(''),处境:stringValue(''),价格:numberValue(0),上架日:numberValue(0)}), 6),今日限购:objectValue({日:stringValue(''),记录:recordValue(IntegerSchema)}),序列:numberValue(0)}),
  祈愿簿:objectValue({日:stringValue(''),今日:arrayValue(z.array(z.any()).max(12)),用过:arrayValue(z.array(z.string()).max(2000)),回访:arrayValue(z.array(z.any()).max(20)),痕迹:arrayValue(z.array(z.string()).max(3)),待生效:arrayValue(z.array(z.any()).max(8)),涩:boolValue(true),来客:stringValue('原生'),上次来客楼层:z.coerce.number().int().default(-99),上次有事楼层:z.coerce.number().int().default(-99),冷却到:z.coerce.number().int().default(-99),用过来客:arrayValue(z.array(z.string()).max(60))}),
  审查:objectValue({难度:stringValue('标准'),日:stringValue(''),今日新增:numberValue(0),最近判定:arrayValue(z.array(objectValue({事由:stringValue(''),难度:stringValue(''),掷出:numberValue(0),目标:numberValue(0),结果:stringValue(''),楼层:numberValue(0),类别:stringValue('')})).max(8)),待核对:stringValue(''),待核对楼层:z.coerce.number().int().default(-1)}),
  信徒培养:objectValue({
