    const cfg=rules.affection||{},book=ensureDevotion(data);
    let delta=Math.round(Number(amount));
    if(delta>0){
      const used=n(book.今日.好感记录[id]),cap=n(cfg.dailyCap)||45;
      delta=Math.min(delta,Math.max(0,cap-used));
