  function addCorruption(data,id,amount){
    const person=data?.重要人物?.[id];
    if(!isAdultFemale(person)||!Number.isFinite(Number(amount))||!amount)return 0;
    const cfg=rules.corruption||{},book=ensureDevotion(data);
