  // 旧档兜底：没有信仰度的具名信徒按等级补一个起点；不该有的人身上不留下这三个字段。
  function ensureDevotion(data){
    const cfg=rules.devotion;
    const book=data.信徒培养=plainObject(data.信徒培养)?data.信徒培养:{};
    book.今日=plainObject(book.今日)?book.今日:{日:'',记录:{}};
    book.今日.日=typeof book.今日.日==='string'?book.今日.日:'';
    book.今日.记录=plainObject(book.今日.记录)?book.今日.记录:{};
    book.待演升级=Array.isArray(book.待演升级)?book.待演升级:[];
    book.赐能待演=Array.isArray(book.赐能待演)?book.赐能待演:[];
    book.觉醒节奏=plainObject(book.觉醒节奏)?book.觉醒节奏:{上次楼层:-99,未出轮数:0};
    book.觉醒节奏.上次楼层=Number.isInteger(book.觉醒节奏.上次楼层)?book.觉醒节奏.上次楼层:-99;
    book.觉醒节奏.未出轮数=n(book.觉醒节奏.未出轮数);
    const key=dayKey(data);
