  // 旧档里的 私密状态 / 私密档案 一次性并进「隐秘档案」，之后只由玩家在人物详情里维护。
  function adoptLegacyDossier(person){
    if(plainObject(person.隐秘档案))return false;
    const legacy=plainObject(person.私密状态)?person.私密状态:null,profile=plainObject(person.私密档案)?person.私密档案:null;
    if(!legacy&&!profile)return false;
    const pick=(value,blank)=>typeof value==='string'&&value.trim()&&value!==blank?value.trim():'';
    const dossier={已生成:true,已鉴赏:false,更新时间:'',亲密关系:'',口腔:'',乳房:pick(profile?.乳房,'未记录'),小穴评级:'',小穴描述:pick(profile?.小穴,'未记录'),小穴特质:'',后穴:pick(profile?.后穴,'未记录'),秘密:pick(legacy?.秘密,'')};
