  // 一条信仰事件：查表算分，受每人每日上限，普通不低于 1、核心不低于 core（不会自动降级）。
  function devote(data,event,id){
    const cfg=rules.devotion,person=data.重要人物?.[event.人物ID];
    if(!plainObject(person))fail('信仰事件要用已建档的人物ID');
    const level=devLevel(person);
    if(!DEVOTION_LEVELS.includes(level))fail('只有信徒才有信仰度');
    const name=person.姓名||event.人物ID;
    if(level==='狂热')return {人物:name,已满:true};
    const table=cfg.reasons[event.事由];
    if(!table)fail('未知信仰事由：'+String(event.事由||'空'));
    const grade=cfg.grades.indexOf(event.程度);
    if(grade<0)fail('程度只能写轻、中、重');
    let raw=table[grade]*(cfg.rate[level]??1);
    // 好感度是信仰乘区：≥60 ×1.25、≥80 ×1.5。
    const boost=affectionBoost(person);
    raw*=boost;
    let delta=raw>0?Math.max(1,Math.ceil(raw)):Math.floor(raw);
    const book=ensureDevotion(data);
    if(delta>0){
      const used=n(book.今日.记录[event.人物ID]),cap=n(cfg.dailyCap[level]);
      delta=Math.min(delta,Math.max(0,cap-used));
      book.今日.记录[event.人物ID]=used+delta;
    }
    const low=level==='普通'?1:cfg.core;
    const high=level==='核心'&&(stage(data)?.rank??0)<cfg.fanaticMinRank?cfg.max-1:cfg.max;
    person.信仰度=Math.max(low,Math.min(high,n(person.信仰度)+delta));
    // 协同：正向信仰事件顺带涨好感；"亲近"再顺带涨堕落。
    if(delta>0){
      addAffection(data,event.人物ID,Math.max(2,Math.round(delta*0.35)));
      if(event.事由==='亲近'&&isAdultFemale(person))addCorruption(data,event.人物ID,[4,8,14][grade]||4);
    }
