  }
  // 好感事件：所有重要人物都能结算，信徒顺带涨信仰，女性"温存"顺带涨堕落。
  function affect(data,event,id){
    const person=data?.重要人物?.[event.人物ID];
    if(!plainObject(person))fail('好感事件要用已建档的人物ID');
    const cfg=rules.affection||{},grades=cfg.grades||['轻','中','重'];
    const grade=grades.indexOf(event.程度);
    const table=cfg.reasons?.[event.事由]||[5,10,16];
    const value=table[grade<0?1:grade];
    const delta=addAffection(data,event.人物ID,value);
    const name=person.姓名||event.人物ID;
    if(delta>0){
      if(event.事由==='温存'&&isAdultFemale(person))addCorruption(data,event.人物ID,[5,10,18][grade<0?1:grade]||5);
      if(DEVOTION_LEVELS.includes(devLevel(person)))addDevotionPoint(data,event.人物ID,Math.max(2,Math.round(delta*0.3)));
