    return {人物:name,好感变化:delta,当前好感:person.好感度,阶段:stageOfAffection(person)};
  }
  // 堕落事件：仅成年女性；男性/未成年直接忽略，不报错。
  function corrupt(data,event,id){
    const person=data?.重要人物?.[event.人物ID];
    if(!plainObject(person))fail('堕落事件要用已建档的人物ID');
    if(!isAdultFemale(person))return {忽略:'男性或未成年角色无堕落值'};
    const cfg=rules.corruption||{},grades=cfg.grades||['轻','中','重'];
    const grade=grades.indexOf(event.程度);
