  // 觉醒：按普通人数加权抽一个群体，给这一轮留一个「新人升核心」的位置。
  function awakeningFor(data,chat,userFloor,userText){
    const cfg=rules.awakening;
    if(!data?.元数据?.开局完成||n(userFloor)<cfg.minFloor)return {fire:false,eligible:false};
    const groups=Object.entries(data.信众群体||{}).filter(([,g])=>n(g.普通)>=cfg.minGroup);
    if(!groups.length)return {fire:false,eligible:false};
    if(cfg.suppressScenes.includes(String(data?.剧情?.场面||'')))return {fire:false,eligible:false};
    const pace=data?.信徒培养?.觉醒节奏||{上次楼层:-99,未出轮数:0};
    if(n(userFloor)-Number(pace.上次楼层??-99)<cfg.gap)return {fire:false,eligible:false};
    if(dropInFor(data,chat,userFloor,userText)||sideQuestFor(data,chat,userFloor).fire)return {fire:false,eligible:false};
    const rand=seeded(`${chat}:${userFloor}:觉醒`);
    const chance=n(pace.未出轮数)>=cfg.pity?100:Math.min(100,cfg.base+cfg.step*n(pace.未出轮数));
    if(rand()*100>=chance)return {fire:false,eligible:true};
    const totalWeight=groups.reduce((sum,[,g])=>sum+n(g.普通),0);let roll=rand()*totalWeight,pick=groups[0];
    for(const row of groups){roll-=n(row[1].普通);if(roll<0){pick=row;break;}}
    const [id,g]=pick,count=n(g.未信仰)+n(g.普通)+n(g.核心)+n(g.狂热);
    const used=new Set(Object.values(data.重要人物||{}).filter(p=>p?.所属群体ID===id&&Number.isInteger(p.群体序号)).map(p=>p.群体序号));
    let slot=0;while(used.has(slot))slot++;
    if(slot>=count)return {fire:false,eligible:true};
    return {fire:true,eligible:true,group:id,name:g.名称||id,slot};
  }
  function awakeningBriefing(data,chat,userFloor,userText){
    const verdict=awakeningFor(data,chat,userFloor,userText);
    if(!verdict.fire)return '';
    return ['【信徒觉醒：已由脚本抽定】',
      `「${verdict.name}」的普通信徒里，有一个人这阵子信仰涨得格外快。本轮让她自然出场：因为一件具体的事（神的一次回应、一场被救下的险情、一个应验的愿望……照眼下的剧情找），她成了神的核心信徒。`,
      `写成剧情，别写成公告。给她起一个符合这个世界的名字，写资料块（成年，信仰等级写核心，所属群体ID 写 ${verdict.group}，群体序号写 ${verdict.slot}），并提交系统事件 {"事件ID":"awake-1","类型":"觉醒","人物ID":"她的ID","群体ID":"${verdict.group}"}。群体人数和信徒总数由脚本改，你不要改。`,
