  }
  // 结算第一步：还原脚本字段、拦掉 AI 直接升级、找出觉醒候选。
  function enforceDevotion(after,old,context){
    const cfg=rules.devotion,notices=[];
    ensureDevotion(after);
    for(const [id,person] of Object.entries(after.重要人物||{})){
      if(!plainObject(person))continue;
      const known=Object.hasOwn(old?.重要人物||{},id),before=known?old.重要人物[id]:null;
      // 信仰度和当前权能只认上一楼脚本算出来的值。
      if(before&&before.信仰度!==undefined)person.信仰度=before.信仰度;else delete person.信仰度;
      if(before&&before.好感度!==undefined)person.好感度=before.好感度;else delete person.好感度;
      if(before&&before.堕落值!==undefined)person.堕落值=before.堕落值;else delete person.堕落值;
      if(before&&Array.isArray(before.当前权能))person.当前权能=clone(before.当前权能);else delete person.当前权能;
      // 私密状态是 0.19 的旧字段，0.20 起由玩家手动建档的「隐秘档案」承载，结算时一律清掉。
      delete person.私密状态;
    }
    // 觉醒候选：脚本已经抽定这一轮要出一个人，AI 写出来的那个人先退回普通，等 applyDevotion 再落实。
    const verdict=awakeningFor(old,context?.chat,context?.userFloor,context?.userText);
    const freshIds=Object.keys(after.重要人物||{}).filter(id=>!Object.hasOwn(old?.重要人物||{},id)&&plainObject(after.重要人物[id]));
    const awakeEvent=(Array.isArray(after.系统事件)?after.系统事件:[]).find(event=>event?.类型==='觉醒');
    let candidate=null;
    if(verdict.fire&&freshIds.length){
      const sameGroup=id=>after.重要人物[id].所属群体ID===verdict.group;
      let id=freshIds.find(x=>sameGroup(x)&&devLevel(after.重要人物[x])==='核心')||freshIds.find(sameGroup);
      if(!id&&awakeEvent&&typeof awakeEvent.人物ID==='string'&&freshIds.includes(awakeEvent.人物ID))id=awakeEvent.人物ID;
      if(id){
        const person=after.重要人物[id];
        if(devLevel(person)==='核心'||devLevel(person)==='狂热')person.信仰等级='普通';
        candidate={id,group:verdict.group||person.所属群体ID};
