        const gid=person.所属群体ID,g=after.信众群体?.[gid],oldGroup=old?.信众群体?.[gid];
        if(g&&oldGroup&&n(g.核心)>n(oldGroup.核心)&&n(g.普通)<n(oldGroup.普通)){g.核心=n(g.核心)-1;g.普通=n(g.普通)+1;}
        if(n(after.信仰?.核心信徒)>n(old?.信仰?.核心信徒)&&n(after.信仰?.普通信徒)<n(old?.信仰?.普通信徒)){after.信仰.核心信徒=n(after.信仰.核心信徒)-1;after.信仰.普通信徒=n(after.信仰.普通信徒)+1;}
      }
    }
    // 拦掉 AI 直接写出来的核心 / 狂热：具名信徒只能靠信仰度升级。入信（→普通）和脱离照旧可以写。
    const totals=faithCounts(after),oldTotals=faithCounts(old),budget={},groupBudget={};
    for(const level of DEVOTION_LEVELS)budget[level]=Math.max(0,n(totals[level])-n(oldTotals[level]));
    for(const [gid,g] of Object.entries(after.信众群体||{})){
      const oldGroup=old?.信众群体?.[gid]||{};groupBudget[gid]={};
      for(const level of DEVOTION_LEVELS)groupBudget[gid][level]=Math.max(0,n(g[level])-n(oldGroup[level]));
    }
    for(const [id,person] of Object.entries(after.重要人物||{})){
      if(!plainObject(person)||(candidate&&candidate.id===id))continue;
      const from=devLevel(old?.重要人物?.[id]),to=devLevel(person);
      if(devotionRank[to]<=devotionRank[from]||!['核心','狂热'].includes(to))continue;
      const back=['普通','核心'].includes(from)?from:'普通';
      const lowered=to+'信徒',raised=back+'信徒';
      if(budget[to]>0){budget[to]--;budget[back]++;after.信仰[lowered]=Math.max(0,n(after.信仰[lowered])-1);after.信仰[raised]=n(after.信仰[raised])+1;}
      const gid=person.所属群体ID,g=gid?after.信众群体?.[gid]:null;
      if(g&&groupBudget[gid]&&groupBudget[gid][to]>0){groupBudget[gid][to]--;groupBudget[gid][back]++;g[to]=Math.max(0,n(g[to])-1);g[back]=n(g[back])+1;}
      person.信仰等级=back;
      notices.push(`${person.姓名||id}的信仰还没到${to}：具名信徒要靠信仰度升级，这次按${back}记。`);
    }
    // 等级变了以后补信仰度。
    for(const [id,person] of Object.entries(after.重要人物||{})){
      if(!plainObject(person))continue;
      const from=devLevel(old?.重要人物?.[id]),to=devLevel(person);
      if(from===to)continue;
      if(to==='普通'){
        if(DEVOTION_LEVELS.includes(from)){
