        }
      }else if(to==='未信仰'){delete person.信仰度;delete person.当前权能;delete person.私密状态;}
      else if(to==='核心'&&from==='狂热'){delete person.私密状态;person.信仰度=Math.min(n(person.信仰度),cfg.max-1);}
    }
    return {candidate,verdict,notices};
  }
  // 结算第三步：落实觉醒、按信仰度升级，只在 AI 楼层做。
  function applyDevotion(after,old,context,pre){
    const notices=[],cfg=rules.devotion;
    if(n(context.floor)<n(context.userFloor))return notices;
    const book=ensureDevotion(after),floor=n(context.floor),rank=stage(after)?.rank??0;
    book.待演升级=book.待演升级.filter(row=>n(row.楼层)===floor);
    book.赐能待演=book.赐能待演.filter(row=>n(row.楼层)===floor);
    const shift=target=>{
      if(!target)return false;
      const moved=n(target.普通)>0;
      if(moved)target.普通=n(target.普通)-1;
      target.核心=n(target.核心)+1;
      return moved;
    };
    const verdict=pre?.verdict||awakeningFor(old,context.chat,context.userFloor,context.userText);
    const candidate=pre?.candidate;
    if(verdict?.fire&&candidate){
