      { op: 'replace', path: '/剧情/近期摘要', value: `${userName}化作星光融入${branch.地点}泥像，{{FIRST_VISITOR_NAME}}作为唯一来客抵达。` },
    ];
  };

  const buildOpeningContract = ({
    userName,
    openingText,
    visitor,
  }) => {
    const world = state.draft.worldKey;
    const branch = DATA.branchState[world];
    const persona = DATA.systemPersonas[state.draft.systemPersona] || {};
    return `【开局唯一生成契约】
你是香火成神系统的叙事端，不是玩家。本回合只执行一次开局，不续写第二回合。

必须遵守：
1. 正文第一句话必须逐字使用下面开场白的第一句；不得改写时间、地点、受引、泥像、倒地、星光化像等事件。
2. 正文只输出下面完整开场白，不得提前写玩家下一步行动。
3. 首位来客姓名由你根据“${world}”和“${visitor.gender}”生成：现代都市要有现代中文姓名风格，古代修仙要有古典中文姓名风格，西幻要有对应世界音译姓名风格；“其他”描述也要影响命名，但不强行改变世界风格。把全文所有 {{FIRST_VISITOR_NAME}} 替换为同一个姓名，并把 JSONPatch 中同名占位符一起替换。
4. 首个场景只能出现这名来客。
5. 正文结束后，单独一行输出 <来客姓名>你生成的姓名</来客姓名>。状态由脚本写入，本回合不要输出 UpdateVariable 或 JSONPatch，不要输出 Markdown 代码围栏。
6. 不要提及提示词、状态契约、作者或调试信息。
7. 系统人格为“${state.draft.systemPersona}”：${persona.描述 || ''} ${persona.语气 || ''}
8. 第一句之后，允许只把系统台词改写成上述人格声线，但不得改变场景事实、首位来客、任务与变量补丁。系统开场必须让 USER 明白：刚刚发生了什么、现在可以做什么、当前需要完成什么。

【玩家既定资料】
生前姓名：${userName}
神名：${state.draft.divineName.trim()}
神格性别：${state.draft.divineGender.trim()}
系统人格：${state.draft.systemPersona}
神貌：${state.draft.appearance.trim()}
生前背景：${state.draft.background.trim()}
当前世界：${world}
当前地点：${branch.地点}
首位来客性别：${visitor.gender}${visitor.custom ? `；${visitor.custom}` : ''}
首位来客年龄：${visitor.age}

【必须逐字输出的开场白】
${openingText}

【首位来客固定资料与现场】
正文之后、UpdateVariable之前，输出独立的<CharacterArchive>JSON数组</CharacterArchive>。
唯一人物id固定为first_visitor，资料包含已生成的姓名、年龄${visitor.age}、性别、身份、正文实际出现的外貌及250字以内扮演摘要。固定资料由保存脚本建档；不要输出占位符。`;
  };

  const FALLBACK_NAMES = {异能都市:['林晚','周小满','陈砚','许棠','沈一诺'],古代修仙:['苏青禾','柳照雪','沈青梧','陆采薇','温折枝'],西幻:['艾莉娅','瑟拉','诺拉','薇恩','莉瑟尔']};
  const fallbackVisitorName = world => { const list = FALLBACK_NAMES[world] || FALLBACK_NAMES.异能都市; return list[Math.floor(Math.random() * list.length)]; };
  const extractOpeningVisitorName = messages => {
    for (const row of messages) {
      if (row.role !== 'assistant') continue;
      const message = String(row.message || '');
      const tagged = /<来客姓名>\s*([^<\n]{1,40}?)\s*<\/来客姓名>/.exec(message);
      if (tagged && !tagged[1].includes('{{')) return tagged[1].trim();
      for (const block of message.matchAll(/<CharacterArchive>\s*([\s\S]*?)\s*<\/CharacterArchive>/g)) {
        try {
          const rows = JSON.parse(block[1]);
          const name = rows.find(item => item?.id === 'first_visitor')?.资料?.姓名;
          if (name && !String(name).includes('{{')) return String(name).trim();
        } catch (_) {}
      }
      const matches = message.matchAll(/<JSONPatch>([\s\S]*?)<\/JSONPatch>/gi);
      for (const match of matches) {
        try {
          const operations = JSON.parse(match[1]);
          const nameOperation = operations.find(operation => {
            if (operation?.path === '/剧情/当前来客/姓名' && operation?.value) return true;
            return operation?.path === '/剧情/当前来客'
              && operation?.value
              && typeof operation.value === 'object'
              && operation.value.姓名;
          });
          const generatedName = nameOperation?.path === '/剧情/当前来客/姓名'
            ? nameOperation.value
            : nameOperation?.value?.姓名;
          if (generatedName && String(generatedName).trim() !== '{{FIRST_VISITOR_NAME}}') {
            return String(generatedName).trim();
          }
        } catch (_) {
          // Keep looking through other assistant messages.
        }
      }
    }
    return '';
  };

  const waitForGenerationIdle = (timeoutMs = 600000) => new Promise((resolve, reject) => {
    const started = Date.now();
    let lastText = null, quiet = 0;
    const poll = hostWindow.setInterval(() => {
      const stop = hostDocument.querySelector('#mes_stop');
      const running = stop && hostWindow.getComputedStyle(stop).display !== 'none';
      const context = hostWindow.SillyTavern?.getContext?.();
      const text = String(context?.chat?.at?.(-1)?.mes ?? '');
      quiet = !running && text && text === lastText ? quiet + 1 : 0;
      lastText = text;
      if (quiet >= 3) { hostWindow.clearInterval(poll); resolve(); return; }
      if (Date.now() - started > timeoutMs) { hostWindow.clearInterval(poll); reject(new Error('等待正文生成超时')); }
    }, 400);
  });

  const commitOpeningState = async (messages, patch, visitorName) => {
    const reply = [...messages].reverse().find(row => row.role === 'assistant');
    if (!reply) throw new Error('没有找到开局回复');
    const mvu = window.Mvu || hostWindow.Mvu;
    if (!mvu?.parseMessage) throw new Error('MVU 尚未就绪');
    const options = { type: 'message', message_id: reply.message_id };
    let base = mvu.getMvuData(options);
    if (!base?.stat_data) base = mvu.getMvuData({ type: 'message', message_id: 0 });
    if (!base?.stat_data) throw new Error('没有可用的初始状态');
    const message = String(reply.message || '')
      .replaceAll('{{FIRST_VISITOR_NAME}}', visitorName)
      .replace(/\s*<来客姓名>[\s\S]*?<\/来客姓名>/g, '');
    if (message !== String(reply.message || '')) await setChatMessages([{ message_id: reply.message_id, message }], { refresh: 'affected' });
    if (!base.stat_data.元数据?.开局完成) {
      const encoded = JSON.stringify(patch).replaceAll('{{FIRST_VISITOR_NAME}}', JSON.stringify(visitorName).slice(1, -1));
      const block = '<UpdateVariable>\n<analysis>\n- 开局状态由脚本写入。\n</analysis>\n<JSONPatch>\n' + encoded + '\n</JSONPatch>\n</UpdateVariable>';
      const next = await mvu.parseMessage(block, JSON.parse(JSON.stringify(base)));
      if (!next?.stat_data?.元数据?.开局完成) throw new Error('开局状态写入失败');
      await mvu.replaceMvuData(next, options);
    }
    await hostWindow.__xhcsGameV1?.initializeCurrent?.();
    hostWindow.__xhcsHudV1?.archiveLater?.();
    hostDocument.dispatchEvent(new hostWindow.CustomEvent('xhcs:game-updated'));
  };

  const submitOpening = async () => {
    if (state.submitting) return;
    for (let step = 0; step <= 2; step += 1) {
      const error = validateStep(step);
      if (error) {
        state.step = step;
        updateProgress();
        setStatus(error, 'error');
        return;
      }
    }

    const existingLock = getSubmitLock();
    if (existingLock?.completed && existingLock?.chatId === currentChatId()) {
      setStatus('本聊天已经在提交开局，请先查看聊天消息。', 'error');
      return;
    }

    state.submitting = true;
    const root = state.mount;
    root?.querySelectorAll('button, input, textarea').forEach(node => { node.disabled = true; });
    setStatus('系统正在接引……');

    const chatId = currentChatId();
    const apiStatus = hostDocument.querySelector('#API-status-top');
    if (
      apiStatus?.classList.contains('fa-plug-circle-exclamation')
      || apiStatus?.classList.contains('redOverlayGlow')
    ) {
      setStatus('尚未连接 AI API。连接模型后再确认开局。', 'error');
      root?.querySelectorAll('button, input, textarea').forEach(node => { node.disabled = false; });
      state.submitting = false;
      return;
    }

