// 参考实现 cleanScene：把状态补丁、归档、思考块、脚本样式和标签剥掉，只留正文。
function cleanScene(value) {
  return String(value == null ? '' : value)
    .replace(/<UpdateVariable>[\s\S]*?(?:<\/UpdateVariable>|$)/gi, '')
    .replace(/<CharacterArchive>[\s\S]*?(?:<\/CharacterArchive>|$)/gi, '')
    .replace(/<thinking>[\s\S]*?(?:<\/thinking>|$)/gi, '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/<[^>]+>/g, '')
    .trim();
}

function sceneText(scene) {
  if (typeof scene === 'string') return scene;
  if (!scene || typeof scene !== 'object') return '';
  const value = scene.text != null ? scene.text
    : scene.content != null ? scene.content
      : scene.message != null ? scene.message
        : scene.mes;
  return value == null ? '' : String(value);
}

// 从正文里挑出提到目标名字的段落（含前后各一段），最多 1800 字，与参考实现一致。
function excerptFor(scene, name) {
  const paragraphs = scene.split(/\n\s*\n/);
  const marks = new Set();
  paragraphs.forEach((paragraph, index) => {
    if (paragraph.indexOf(name) === -1) return;
    [index - 1, index, index + 1].forEach(near => {
      if (near >= 0 && near < paragraphs.length) marks.add(near);
    });
  });
  const picked = [...marks].sort((a, b) => a - b).map(index => paragraphs[index]).join('\n\n');
  return (picked || scene).slice(0, 1800);
}

// 参考实现 collectCharacterScenes 的纯逻辑版：只收提到这个人的楼层，按时间顺序，过多时保留初遇与最近场次。
function collectScenes(messages, name, limit = 24) {
  const rows = Array.isArray(messages) ? messages : [];
  const wanted = cleanText(name);
  const max = Math.max(0, Math.floor(Number(limit) || 0));
  if (!wanted || !max) return [];
  const hits = [];
  rows.forEach((row, index) => {
    const scene = cleanScene(sceneText(row));
    if (!scene || scene.indexOf(wanted) === -1) return;
    if (scene.indexOf('【开局设定】') !== -1) return;
    const floor = Number.isFinite(row.floor) ? row.floor
      : Number.isFinite(row.index) ? row.index : index + 1;
    const role = cleanText(row.role) || (row.isUser || row.is_user ? 'user' : 'assistant');
    hits.push({ floor, role, text: excerptFor(scene, wanted) });
  });
  if (hits.length <= max) return hits;
  const head = Math.min(6, Math.max(0, max - 1));
  const tail = max - head;
  return head ? hits.slice(0, head).concat(hits.slice(-tail)) : hits.slice(-tail);
}

// 按正则在句子里挑证据：最多 3 句、不重复、按原顺序拼接。
function pickSentences(sentences, pattern, maxLength) {
  const picked = [];
  for (let i = 0; i < sentences.length && picked.length < 3; i++) {
    if (!pattern.test(sentences[i])) continue;
    if (picked.indexOf(sentences[i]) === -1) picked.push(sentences[i]);
  }
  const out = picked.join('。');
  return maxLength ? out.slice(0, maxLength) : out;
}

