function clipTrait(value) {
  const out = cleanText(value);
  if (!out) return '';
  if (out.length <= MAX_FIELD_LEN) return out;
  const firstClause = out.split(/[，,。；;！!？?]/)[0].trim();
  return (firstClause && firstClause.length <= MAX_FIELD_LEN ? firstClause : out).slice(0, MAX_FIELD_LEN);
}

// 0.21.0：单字段硬上限 30 字。优先在句读处截断，避免半截词；
// 句读太靠前（<14 字）就退化成硬切，并去掉尾巴上残留的标点。
function clipField(value, maxLen = MAX_FIELD_LEN) {
  const limit = Number(maxLen) > 0 ? Math.floor(Number(maxLen)) : MAX_FIELD_LEN;
  const raw = cleanText(value, limit * 3).replace(/\n+/g, ' ');
  if (!raw) return '';
  if (raw.length <= limit) return raw;
  const sliced = raw.slice(0, limit);
  const lastPunct = Math.max(
    sliced.lastIndexOf('。'),
    sliced.lastIndexOf('；'),
    sliced.lastIndexOf('！'),
    sliced.lastIndexOf('，'),
    sliced.lastIndexOf('、')
  );
  if (lastPunct >= 14) return sliced.slice(0, lastPunct) + (sliced[lastPunct] === '。' ? '。' : '');
  return sliced.replace(/[，、；：,.!?\s]+$/g, '');
}

function firstText(list) {
  for (let i = 0; i < list.length; i++) {
