// 从模型回复里抠出 JSON：允许 ```json 包裹，也允许前后有废话；失败返回 null。
// 0.21.0：模型偶尔会把 JSON 写成"接近合法"的样子（尾逗号、裸键、值里换行），
// 这里先按原样解析，失败再做最小修补；仍失败就返回 null，由调用方重试。
function balancedObject(value) {
  const text = String(value || '');
  const start = text.indexOf('{');
  if (start < 0) return '';
  let depth = 0, inString = false, escaped = false;
  for (let index = start; index < text.length; index++) {
    const ch = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return text.slice(start, index + 1);
    }
  }
  return '';
}

function repairJson(value) {
  return String(value || '')
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, ' ')
    .replace(/[“”]/g, '"')
    .replace(/"\s*：/g, '":')
    .replace(/，(?=\s*["'])/g, ',')
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/([{,]\s*)([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5]*)\s*[:：]/g, '$1"$2":');
}

function parseGenerated(text) {
  if (text && typeof text === 'object' && !Array.isArray(text)) return text;
  const source = typeof text === 'string' ? text : text && typeof text.content === 'string' ? text.content : '';
  const body = String(source == null ? '' : source).trim()
    .replace(/^\uFEFF/, '')
    .replace(/```json/gi, ' ')
    .replace(/```/g, ' ')
    .replace(/[\u200b-\u200d\uFEFF]/g, '')
    .trim();
  const start = body.indexOf('{');
  const end = body.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  const slices = [...new Set([balancedObject(body), body.slice(start, end + 1)].filter(Boolean))];
  for (const slice of slices) {
    for (const attempt of [slice, repairJson(slice)]) {
      try {
        const parsed = JSON.parse(attempt);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
      } catch (_) { /* 下一个候选 */ }
    }
  }
  return null;
}

