  }

  /* ==================== 定位宿主页面 ====================
   * 本模块由角色卡在酒馆页面里载入（不是酒馆助手的 iframe），
   * 界面直接挂当前 document，不再去找外层窗口。
   */
  var PAGE = (function () {
