  var CSS = "/* ==== 注入宿主样式（脚本版专有） ====
   变量在这里重新声明一遍，不依赖从酒馆页面继承，
   免得宿主环境的样式差异把面板配色带偏。 */
:host{
  position:fixed;inset:0;z-index:2147483000;display:block;
  --bg:#120a13;--bg-glow-1:rgba(150,62,156,.22);--bg-glow-2:rgba(214,189,150,.06);
  --card:rgba(238,222,242,.045);--card-2:rgba(238,222,242,.07);
  --line:rgba(232,214,236,.10);--line-2:rgba(232,214,236,.18);
  --hot:#c06cc2;--hot-2:#e2b6df;--hot-deep:#76207a;--cyan:#d6bd96;--amber:#eba866;
  --cyan-a08:rgba(214,189,150,.08);--cyan-a40:rgba(214,189,150,.40);--cyan-a75:rgba(214,189,150,.75);
  --hot-a12:rgba(192,108,194,.12);--hot-a20:rgba(192,108,194,.20);--hot-a28:rgba(192,108,194,.28);
  --hot-a35:rgba(192,108,194,.35);--hot-a45:rgba(192,108,194,.45);--hot-a55:rgba(192,108,194,.55);
  --hot-a75:rgba(192,108,194,.75);
  --text:#f4ece3;--dim:#b9a5ad;--dim-2:#958290;
  --r:16px;--safe-t:0px;--safe-b:0px;
  --font:"PingFang SC","HarmonyOS Sans SC","Hiragino Sans GB","Source Han Sans SC","Microsoft YaHei",system-ui,-apple-system,sans-serif;
}
#btn-close{display:none}

/* ============================================================
   TOY·LINK 手机端遥控器
   单文件前端卡，零构建。运行环境：酒馆助手（Tavern Helper）iframe

   两套主题靠变量切换（和悬浮球一套：梅紫硅胶 · 奶白底盘 · 香槟金环，哑光不反光）：
     · 遥控器在你手里（默认）→ 梅紫 + 香槟金，底色梅黑
     · 遥控器在 TA 手里     → 酒红 / 石榴红 + 香槟金，主导权不在你手上
   --cyan 沿用旧名，现在是香槟金（第二强调色：累积环、选中芯片、余像线）。
   除背景渐变外不写第二套规则，全部靠变量自动跟随。
   ============================================================ */
:root{
  --bg:#120a13;
  --bg-glow-1:rgba(150,62,156,.22);
  --bg-glow-2:rgba(214,189,150,.06);
  --card:rgba(238,222,242,.045);
  --card-2:rgba(238,222,242,.07);
  --line:rgba(232,214,236,.10);
  --line-2:rgba(232,214,236,.18);
  --hot:#c06cc2;
  --hot-2:#e2b6df;
  --hot-deep:#76207a;
  --hot-a12:rgba(192,108,194,.12);
  --hot-a20:rgba(192,108,194,.20);
  --hot-a28:rgba(192,108,194,.28);
  --hot-a35:rgba(192,108,194,.35);
  --hot-a45:rgba(192,108,194,.45);
  --hot-a55:rgba(192,108,194,.55);
  --hot-a75:rgba(192,108,194,.75);
  --cyan:#d6bd96;
  --cyan-a08:rgba(214,189,150,.08);
  --cyan-a40:rgba(214,189,150,.40);
  --cyan-a75:rgba(214,189,150,.75);
  --amber:#eba866;
  --text:#f4ece3;
  --dim:#b9a5ad;
  --dim-2:#958290;
  --r:16px;
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --font:"PingFang SC","HarmonyOS Sans SC","Hiragino Sans GB","Source Han Sans SC","Microsoft YaHei",system-ui,-apple-system,sans-serif;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{height:100%;margin:0}
body{
  font-family:var(--font);
  color:var(--text);
  background:var(--bg);
  overflow:hidden;
  overscroll-behavior:none;
  -webkit-font-smoothing:antialiased;
}
button,input{font-family:inherit;color:inherit}
button{border:0;background:none;cursor:pointer}

/* ---------- 舞台与手机外壳 ---------- */
#shell{
  position:relative;
  width:100%;height:100dvh;height:100vh;min-height:600px;min-height:100vh;
  display:flex;flex-direction:column;
  overflow:hidden;
  font-family:var(--font);
  color:var(--text);
  /* 底色用常量，不依赖 CSS 变量；渐变叠在上面，即使变量失效也不会透出底下的内容 */
  background-color:#120a13;
  background-image:
    radial-gradient(120% 70% at 12% -8%, var(--bg-glow-1), transparent 62%),
    radial-gradient(110% 60% at 92% 6%, var(--bg-glow-2), transparent 58%),
    linear-gradient(180deg,#1b0e1d 0%, #120a13 55%, #09050a 100%);
}
#shell::after{
  content:"";position:absolute;inset:0;pointer-events:none;opacity:.5;
  background-image:linear-gradient(rgba(232,214,236,.018) 1px,transparent 1px),
                   linear-gradient(90deg,rgba(232,214,236,.018) 1px,transparent 1px);
  background-size:26px 26px;
  mask-image:radial-gradient(120% 80% at 50% 0%,#000 30%,transparent 100%);
}
@media (min-width:860px){
  body{display:grid;place-items:center;background:#060307}
  #shell{
    width:404px;height:min(800px,92vh);max-height:92vh;min-height:0;
    border-radius:34px;
    border:1px solid rgba(232,214,236,.09);
    box-shadow:0 40px 120px rgba(0,0,0,.75),0 0 0 10px rgba(232,214,236,.02);
  }
}
/* 全屏模式：窄屏默认就是全屏；宽屏可以手动切换 */
#shell.fit{
  width:100%;height:100dvh;height:100vh;max-height:none;min-height:0;
  border-radius:0;border:0;box-shadow:none;
}

/* ---------- 顶栏 ---------- */
.bar{
  position:relative;z-index:5;flex:none;
  display:flex;align-items:center;gap:10px;
  padding:calc(var(--safe-t) + 12px) 16px 12px;
}
.brand{display:flex;align-items:center;gap:8px;min-width:0}
.logo{
  /* 装置本体（和悬浮球同一只 C 形）：梅紫哑光硅胶 + 香槟金环，不垫底盘、不画高光 */
  width:30px;height:30px;flex:none;display:grid;place-items:center;
  filter:drop-shadow(0 1.5px 2px rgba(0,0,0,.5));
}
.logo svg{width:30px;height:30px;display:block;overflow:visible}
.brand b{
  font-size:12px;letter-spacing:.22em;font-weight:700;text-transform:uppercase;
  white-space:nowrap;color:var(--text);
}
.brand b i{font-style:normal;color:var(--cyan)}
.brand .ver{
  font-size:9.5px;letter-spacing:.06em;color:var(--dim-2);
  white-space:nowrap;margin-left:-2px;
}
.conn{
  margin-left:auto;display:flex;align-items:center;gap:6px;
  font-size:11px;color:var(--dim);
  padding:5px 10px;border:1px solid var(--line);border-radius:999px;
  background:var(--card);white-space:nowrap;
}
.dot{width:7px;height:7px;border-radius:50%;background:var(--dim-2);flex:none}
/* 已连接：固定绿灯闪烁，不跟主题走 —— 它是状态指示，不是装饰。
   跟着主题变会让「连上了」这件事在两档下颜色不同，反而不好认。 */
.dot.live{background:#5fd08e;box-shadow:0 0 6px rgba(95,208,142,.55);animation:pulse 1.6s ease-in-out infinite}
.dot.demo{background:var(--amber);box-shadow:0 0 5px var(--amber)}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.25}}

/* 顶栏小按钮 */
.bar-btn{
  flex:none;width:30px;height:30px;margin-left:8px;border-radius:10px;
  border:1px solid var(--line);background:var(--card);color:var(--dim);
  font-size:12px;line-height:1;display:grid;place-items:center;
}
.bar-btn:active{transform:scale(.94)}
@media (max-width:859px){ .bar-btn.narrow-hide{display:none} }

/* ---------- 作用对象切换（常驻，面板最上方） ----------
   这一档换的不是参数，是整台机器谁说了算：
   你操控 = 遥控台（梅紫、可点）；TA 操控 = 只读仪表（酒红、锁住档位）。 */
.tgtbar{
  position:relative;z-index:6;flex:none;
  display:grid;grid-template-columns:1fr 1fr;gap:4px;
  margin:0 16px 12px;padding:4px;border-radius:15px;
  border:1px solid var(--line);background:rgba(238,222,242,.035);
}
.tgt-ind{
  position:absolute;top:4px;bottom:4px;left:4px;width:calc(50% - 6px);
  border-radius:11px;pointer-events:none;
  background:linear-gradient(180deg,var(--hot-a28),var(--hot-a12));
  border:1px solid var(--hot-a45);
  box-shadow:0 2px 10px rgba(0,0,0,.25);
  transition:transform .3s cubic-bezier(.4,0,.2,1),background .3s,border-color .3s,box-shadow .3s;
}
.tgt{
  position:relative;z-index:1;padding:9px 6px;border-radius:11px;
  display:flex;flex-direction:column;align-items:center;gap:2px;
  color:var(--dim);transition:color .22s;
}
.tgt b{font-size:12.5px;font-weight:700;letter-spacing:.02em;white-space:nowrap}
.tgt i{font-style:normal;font-size:9.5px;letter-spacing:.04em;opacity:.7;white-space:nowrap}
.tgt.on{color:var(--text)}
.tgt.on i{opacity:.85}

/* 目标条已锁定：这里不再有作用对象切换，这条规则只给旧存档的样式兜底。 */
.tgtbar.locked{opacity:.45}
.tgtbar.locked .tgt{cursor:not-allowed}
.tgtbar.locked .tgt-ind{filter:grayscale(.55)}
.tgtbar.locked .tgt:active{transform:none}

/* 切到 TA 拿着遥控器：主导权不在你手上，整机从梅紫换成酒红 / 石榴红（悬浮球晕光同步变红）。
   香槟金不变，还是同一个牌子；这里只换变量和背景，其余规则全部靠 var() 自动跟随。 */
#shell.tgt-user{
  --hot:#e0566f;
  --hot-2:#f2b0ba;
  --hot-deep:#8a1a33;
  --hot-a12:rgba(224,86,111,.12);
  --hot-a20:rgba(224,86,111,.20);
  --hot-a28:rgba(224,86,111,.28);
  --hot-a35:rgba(224,86,111,.35);
  --hot-a45:rgba(224,86,111,.45);
  --hot-a55:rgba(224,86,111,.55);
  --hot-a75:rgba(224,86,111,.75);
  --bg-glow-1:rgba(176,34,68,.26);
  --bg-glow-2:rgba(214,189,150,.06);
  --card:rgba(250,226,230,.045);
  --card-2:rgba(250,226,230,.07);
  --line:rgba(244,214,220,.10);
  --line-2:rgba(244,214,220,.18);
  --text:#f6ebe5;
  --dim:#bfa2a5;
  --dim-2:#9a7f83;
  background-color:#13070a;
  background-image:
    radial-gradient(120% 70% at 12% -8%, var(--bg-glow-1), transparent 62%),
    radial-gradient(110% 60% at 92% 6%, var(--bg-glow-2), transparent 58%),
    linear-gradient(180deg,#1e0a10 0%, #13070a 55%, #0a0305 100%);
}
#shell.tgt-user .tgt-ind{transform:translateX(calc(100% + 4px))}
/* 圆环渐变：两个停靠点跟着主色走 */
.ring .s1{stop-color:var(--cyan)}
.ring .s2{stop-color:var(--hot)}
.ring .s3{stop-color:var(--hot-2)}
#v-device.locked .ring .s3{stop-color:var(--hot-2)}

/* 遥控器在 TA 手里时，档位控件整体降级为只读仪表 */
.lockbar{
  margin:0 0 12px;padding:10px 13px;border-radius:13px;
  border:1px dashed var(--hot-a45);background:var(--hot-a12);
  display:flex;flex-direction:column;gap:3px;
}
.lockbar b{font-size:12px;color:var(--hot-2);letter-spacing:.04em}
.lockbar span{font-size:11px;color:var(--dim);line-height:1.55}
.lockbar[hidden]{display:none}
.lockbar.pending{border-style:solid;animation:lockpulse 1.5s ease-in-out infinite}
@keyframes lockpulse{0%,100%{opacity:1}50%{opacity:.5}}

/* 请求停止：遥控器在 TA 手里时，这是玩家唯一还能做的事。
   放在电源区上方常驻，不跟着内容滚 —— 做成呼吸的样子，因为它得一直勾着人去按。
   配色走琥珀而不是主色：主色是"谁在掌控"，求饶是另一回事，混在一起两个按钮会糊成一团。 */
.begbar{flex:none;padding:0 16px 10px}
.begbar[hidden]{display:none}
.beg{
  display:flex;flex-direction:column;align-items:center;gap:3px;
  width:100%;padding:12px 14px;border-radius:14px;
  border:1px solid rgba(235,168,102,.48);
  background:linear-gradient(180deg,rgba(235,168,102,.16),rgba(235,168,102,.06));
  animation:begbreath 3.2s ease-in-out infinite;
}
.beg b{font-size:13.5px;font-weight:700;letter-spacing:.06em;color:#f6d3a8}
.beg i{font-style:normal;font-size:10.5px;color:var(--dim);letter-spacing:.04em;text-align:center}
.beg:active{transform:scale(.985)}
.beg:disabled{animation:none;opacity:.6}
@keyframes begbreath{
  0%,100%{box-shadow:0 0 0 0 rgba(235,168,102,.20)}
  50%{box-shadow:0 0 18px 1px rgba(235,168,102,.20)}
}

/* 只读态：能看不能碰。当前档位仍然高亮，因为它就是"TA 现在用的是哪一档" */
#v-device.locked .modes{opacity:.5}
#v-device.locked .mode{cursor:default;transition:none}
/* 真 disabled 的按钮会被浏览器套上灰字色，会把 currentColor 的图标一起带灰，改回来 */
#v-device.locked .mode:disabled{color:inherit}
#v-device.locked .mode:active{transform:none}
#v-device.locked .mode.on{
  opacity:1;
  border-color:var(--hot-a75);
  background:linear-gradient(180deg,var(--hot-a20),var(--hot-a12));
  box-shadow:none;
}
#v-device.locked .ctl input[type=range]{opacity:.55;pointer-events:none}
#v-device.locked .ctl input[type=range]::-webkit-slider-thumb{box-shadow:none}
#v-device.locked #dur-chips{opacity:.5;pointer-events:none}
#v-device.locked .chip{cursor:default}
#v-device.locked .chip:active{transform:none}

/* ---------- 主舞台 ---------- */
.stage{
  position:relative;z-index:2;flex:1 1 auto;min-height:0;
  overflow-y:auto;overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  padding:2px 16px 20px;
  scrollbar-width:none;
}
.stage::-webkit-scrollbar{display:none}
.stage[hidden]{display:none}

/* ---------- 圆环仪表 ---------- */
.hero{
  position:relative;
  display:grid;place-items:center;
  padding:6px 0 4px;
}
.ring{position:relative;width:min(232px,56vw,30vh);height:min(232px,56vw,30vh)}
@media (max-height:700px){
  .wave-wrap{height:52px}
  .readout .big{font-size:clamp(30px,10vw,42px)}
}
.ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.ring .trk{fill:none;stroke:rgba(232,214,236,.07);stroke-width:7}
.ring .val{fill:none;stroke:url(#gr);stroke-width:7;stroke-linecap:round;
  transition:stroke-dasharray .12s linear}
.ring .val2{fill:none;stroke:var(--cyan-a75);stroke-width:3;stroke-linecap:round}
.readout{
  position:absolute;inset:0;display:grid;place-content:center;text-align:center;gap:2px;
}
.readout .big{
  font-size:clamp(38px,13vw,54px);font-weight:800;line-height:1;letter-spacing:-.02em;
  font-variant-numeric:tabular-nums;color:var(--text);
}
.readout .big small{font-size:.38em;font-weight:600;letter-spacing:.06em;color:var(--dim);margin-left:4px}
.readout .sub{font-size:11.5px;color:var(--dim);letter-spacing:.14em;font-variant-numeric:tabular-nums}
.readout .mode-tag{
  margin-top:6px;font-size:11px;color:var(--hot-2);letter-spacing:.2em;
  text-transform:uppercase;
}
.ring.off .val{stroke:rgba(232,214,236,.10)}
.ring.off .big{color:var(--dim);text-shadow:none}

/* ---------- 波形 ---------- */
.wave-wrap{
  position:relative;margin:10px 0 2px;height:66px;border-radius:14px;
  border:1px solid var(--line);background:linear-gradient(180deg,rgba(238,222,242,.035),rgba(238,222,242,.01));
  overflow:hidden;
}
.wave-wrap canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.wave-tag{
  position:absolute;left:10px;top:7px;font-size:9.5px;letter-spacing:.2em;
  color:var(--dim-2);text-transform:uppercase;
}

/* ---------- 阶段进度 ---------- */
.phases{display:flex;gap:6px;margin:12px 0 4px}
.phase{flex:1;height:4px;border-radius:4px;background:rgba(232,214,236,.09);overflow:hidden}
.phase i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--hot));transition:width .3s}
.phase.done i{width:100%}
.freeze{
  margin:9px 0 0;padding:7px 12px;border-radius:10px;text-align:center;
  font-size:11.5px;letter-spacing:.05em;color:var(--cyan);cursor:pointer;
  border:1px dashed var(--cyan-a40);background:var(--cyan-a08);
}
.freeze:active{transform:scale(.99)}
.freeze[hidden]{display:none}
.phase-head{display:flex;justify-content:space-between;font-size:11px;color:var(--dim);letter-spacing:.1em}
.phase-head b{color:var(--text);font-weight:600}

/* ---------- 通用面板 ---------- */
.panel{
  margin-top:14px;padding:14px;border-radius:var(--r);
  border:1px solid var(--line);background:var(--card);
  backdrop-filter:blur(6px);
}
.panel h3{
  margin:0 0 11px;font-size:10.5px;letter-spacing:.2em;color:var(--dim-2);
  text-transform:uppercase;font-weight:700;
}
.panel h3 .tag{
  margin-left:8px;padding:2px 8px;border-radius:999px;
  font-size:9.5px;letter-spacing:.06em;text-transform:none;font-weight:600;
  color:var(--amber);background:rgba(235,168,102,.10);
  border:1px solid rgba(235,168,102,.32);
}
.panel h3 .tag:empty{display:none}

/* ---------- 模式网格 ---------- */
.modes{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
@media (max-width:360px){.modes{grid-template-columns:repeat(3,1fr)}}
.mode{
  position:relative;padding:11px 4px 9px;border-radius:13px;
  border:1px solid var(--line);background:rgba(238,222,242,.025);
  display:flex;flex-direction:column;align-items:center;gap:5px;
  transition:transform .12s,border-color .18s,background .18s;
}
.mode:active{transform:scale(.94)}
.mode svg{width:26px;height:26px;opacity:.8;color:var(--cyan)}
.mode span{font-size:10.5px;letter-spacing:.04em;color:var(--dim)}
.mode.on{
  border-color:var(--hot-a75);
  background:linear-gradient(180deg,var(--hot-a20),var(--hot-a12));
  box-shadow:0 4px 14px rgba(0,0,0,.22);
}
.mode.on svg{opacity:1;color:var(--hot-2)}
.mode.on span{color:var(--text);font-weight:600}

/* ---------- 滑块 ---------- */
.ctl{display:block;margin-top:14px}
.ctl:first-of-type{margin-top:0}
.ctl .row{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}
.ctl .row span{font-size:12px;color:var(--dim);letter-spacing:.08em}
.ctl .row b{
  font-size:15px;font-weight:700;font-variant-numeric:tabular-nums;
  color:var(--text);letter-spacing:.02em;
}
.ctl .row b em{font-style:normal;font-size:10.5px;color:var(--dim);margin-left:2px;letter-spacing:.06em}
input[type=range]{
  -webkit-appearance:none;appearance:none;width:100%;height:30px;background:transparent;
}
input[type=range]::-webkit-slider-runnable-track{
  height:6px;border-radius:6px;
  background:linear-gradient(90deg,var(--hot) var(--p,50%),rgba(232,214,236,.10) var(--p,50%));
}
input[type=range]::-webkit-slider-thumb{
  -webkit-appearance:none;width:22px;height:22px;margin-top:-8px;border-radius:50%;
  background:#f6efe7;border:3px solid var(--hot);
  box-shadow:0 2px 6px rgba(0,0,0,.4);
}
input[type=range]::-moz-range-track{height:6px;border-radius:6px;background:rgba(232,214,236,.10)}
input[type=range]::-moz-range-progress{height:6px;border-radius:6px;background:var(--hot)}
input[type=range]::-moz-range-thumb{
  width:22px;height:22px;border-radius:50%;background:#f6efe7;border:3px solid var(--hot);
}

/* ---------- 快捷芯片 ---------- */
.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.chip{
  padding:7px 12px;border-radius:999px;font-size:11.5px;color:var(--dim);
  border:1px solid var(--line);background:rgba(238,222,242,.025);
}
.chip.on{border-color:var(--cyan-a75);color:#efe0c6;background:var(--cyan-a08)}
.chip:active{transform:scale(.96)}

/* ---------- 电源键 ---------- */
.powerbar{
  position:relative;z-index:5;flex:none;display:flex;gap:10px;
  padding:12px 16px calc(var(--safe-b) + 12px);
  border-top:1px solid var(--line);
  background:linear-gradient(180deg,rgba(10,5,10,.35),rgba(10,5,10,.92));
  backdrop-filter:blur(12px);
}
.power{
  flex:1;padding:15px;border-radius:15px;font-size:14.5px;font-weight:700;letter-spacing:.1em;
  background:linear-gradient(160deg,var(--hot) -35%,var(--hot-deep,#76207a) 90%);
  color:#fbf6f0;box-shadow:0 6px 18px rgba(0,0,0,.35);
  transition:transform .12s,filter .2s;
}
.power:active{transform:scale(.975)}
.power.stop{background:linear-gradient(160deg,#352a36,#1f1720);color:var(--text);box-shadow:none;border:1px solid var(--line-2)}
.ghost{
  flex:none;width:56px;border-radius:15px;border:1px solid var(--line);
  background:var(--card);display:grid;place-items:center;font-size:19px;color:var(--cyan);
}
.ghost:active{transform:scale(.95)}

/* ---------- 视图切换 ---------- */
.dock{
  position:relative;z-index:5;flex:none;display:flex;
  border-top:1px solid var(--line);
  padding-bottom:var(--safe-b);background:rgba(10,5,10,.92);
}
.tab{
  flex:1;padding:10px 4px calc(10px + var(--safe-b)/2);font-size:11px;color:var(--dim-2);
  letter-spacing:.1em;position:relative;
}
.tab.on{color:var(--text)}
.tab.on::after{
  content:"";position:absolute;left:50%;top:0;transform:translateX(-50%);
  width:26px;height:2px;border-radius:2px;background:var(--cyan);
}
.tab b{display:block;font-size:16px;font-weight:400;margin-bottom:3px}
.tab.on b{color:var(--cyan)}

/* ---------- 对话流 ---------- */
.say{
  position:sticky;top:0;z-index:4;display:flex;gap:8px;
  padding:7px 0 11px;
  background:linear-gradient(180deg,rgba(13,7,11,.97) 30%,rgba(13,7,11,.72) 78%,rgba(13,7,11,0));
}
.say input{
  flex:1;min-width:0;padding:11px 14px;border-radius:12px;font-size:16px;
  border:1px solid var(--line);background:rgba(0,0,0,.42);outline:none;
}
.say input:focus{border-color:var(--hot-a55)}
.say button{
  flex:none;padding:0 18px;border-radius:12px;font-size:13px;font-weight:700;color:#fbf6f0;
  background:linear-gradient(160deg,var(--hot) -35%,var(--hot-deep) 90%);
}
.say button:active{transform:scale(.96)}
.feed{display:flex;flex-direction:column;gap:12px;padding:4px 0 8px}
.feed-empty{
  text-align:center;color:var(--dim-2);font-size:12px;line-height:2;
  padding:56px 20px;letter-spacing:.08em;
}
.msg{max-width:100%;animation:rise .45s cubic-bezier(.2,.7,.3,1)}
@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.msg .who{
  display:flex;align-items:center;gap:7px;font-size:10.5px;color:var(--dim-2);
  letter-spacing:.16em;text-transform:uppercase;margin-bottom:6px;
}
.msg .who i{width:16px;height:16px;border-radius:5px;background:linear-gradient(160deg,var(--hot),var(--hot-deep));display:block}
.msg .bubble{
  padding:12px 14px;border-radius:14px;font-size:13.5px;line-height:1.75;
  background:var(--card-2);border:1px solid var(--line);white-space:pre-wrap;word-break:break-word;
}
.msg.me .bubble{background:var(--hot-a12);border-color:var(--hot-a28)}
.msg.sys .bubble{
  background:transparent;border-style:dashed;color:var(--dim);font-size:11.5px;padding:8px 12px;
}
.msg.now .bubble{box-shadow:0 0 0 1px var(--cyan-a40)}
.blink::after{content:"▍";color:var(--cyan);animation:pulse 1s infinite}

/* ---------- 设置页 ---------- */
.field{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:12px 0;border-bottom:1px solid var(--line);
}
.field:last-child{border-bottom:0}
.field .lb{min-width:0}
.field .lb b{display:block;font-size:13px;font-weight:600;margin-bottom:3px}
.field .lb small{display:block;font-size:11px;color:var(--dim-2);line-height:1.5}
.sw{
  position:relative;width:46px;height:27px;border-radius:999px;flex:none;
  background:rgba(232,214,236,.10);border:1px solid var(--line);transition:background .2s;
}
.sw i{
  position:absolute;top:2.5px;left:2.5px;width:20px;height:20px;border-radius:50%;
  background:#f6efe7;transition:transform .2s;
}
.sw.on{background:linear-gradient(160deg,var(--hot) -20%,var(--hot-deep) 100%);border-color:transparent}
.sw.on i{transform:translateX(19px)}
.mini{
  flex:none;padding:8px 13px;border-radius:10px;font-size:12px;
  border:1px solid var(--line);background:var(--card);color:var(--dim);
}
.mini:active{transform:scale(.96)}
.num{
  width:64px;padding:8px 10px;border-radius:10px;text-align:center;font-size:13px;
  border:1px solid var(--line);background:rgba(0,0,0,.35);
}
textarea{
  width:100%;min-height:96px;margin-top:10px;padding:11px 12px;border-radius:12px;
  border:1px solid var(--line);background:rgba(0,0,0,.35);color:var(--text);
  font-size:12.5px;line-height:1.6;font-family:var(--font);resize:vertical;
}
.hint{font-size:11px;color:var(--dim-2);line-height:1.7;margin-top:8px}

/* ---------- 吐司 ---------- */
#toast{position:absolute;left:50%;bottom:12%;transform:translateX(-50%);z-index:99;
  display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}
.tst{
  padding:9px 16px;border-radius:999px;font-size:12px;
  background:rgba(24,14,25,.95);border:1px solid var(--line-2);
  box-shadow:0 8px 30px rgba(0,0,0,.6);animation:tin .25s;max-width:82vw;text-align:center;
}
@keyframes tin{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
