    if(canHaveDossier(person))try{renderDossierPanel(dialog,id,person,root);}catch(error){console.warn('[香火成神] 隐秘档案面板没渲染',error);}
    const controls=createEl('div','xhcs-companion-actions xhcs-profile-actions');
