    controls.append(companionButton('更换头像',()=>avatar.click()),companionButton('归档人物资料',()=>{
      const current=window.Mvu?.getMvuData?.({type:'message',message_id:latestAssistantMessage()?.message_id})?.stat_data?.重要人物?.[id];
      if(!current)throw Error('人物已不存在');return distillCharacter(fixedCharacter(id,current),id);
    }));
    const remove=companionButton('删除人物',async()=>{
      const tuple=companionTuple(),stored=window.Mvu.getMvuData({type:'message',message_id:tuple.floor})?.stat_data?.重要人物?.[id];
      if(!stored)throw Error('人物已不存在');const expected=JSON.stringify(stored),profile=fixedCharacter(id,stored);
      if(!await confirmCompanionAction({title:'删除人物',message:`确认删除「${profile.姓名||id}」？将移除当前存档的人物资料和在场记录，信徒总数与历史消息不变。`,label:'确认删除',root,opener:remove,kind:'delete'}))return;
      await mutateCompanions(data=>{
        if(JSON.stringify(data.重要人物?.[id])!==expected)throw Error('人物资料已变化，请重新打开资料后删除');
        XhcsCompanions.remove(data,id,profile,tuple);
