    dialog.append(avatarOwner);
    dialog.append(controls);open();
  };
  // ── 隐秘档案（核心 / 狂热专属）：玩家点「生成」才建，AI 改不动 ──────────────
  const dossierApi = () => {
    const api = hostWindow.XhcsSecretDossier;
    if (!api) throw Error('隐秘档案模块还没就绪，请刷新页面');
    return api;
  };
  const dossierLevels = ['核心', '狂热'];
  const dossierSignature = dossier => JSON.stringify([dossier?.已生成 === true, dossier?.已鉴赏 === true, text(dossier?.小穴评级), text(dossier?.更新时间)]);
  // 年龄通常只存在人物档案里（变量只留姓名、等级、档案版本和现场字段），读不到时按成年算：
  // Schema 那边只收成年人物，真正的门槛是信仰等级。
  // 0.21.0：隐秘档案只给成年女性，男性角色严禁拥有。
  const isFemaleFollower = person => {
    const gender = text(person?.性别).trim();
    if (!gender || gender.includes('男')) return false;
    return gender === '女' || gender === '女性' || gender.includes('女') || gender.includes('雌') || gender.includes('母');
  };
  // 0.24.0：核心/狂热，或好感度 ≥60、堕落值 ≥60 的成年女性也能建档。
  const canHaveDossier = person => isFemaleFollower(person)
    && (Number.isFinite(Number(person?.年龄)) ? Number(person.年龄) >= 18 : true)
    && (dossierLevels.includes(text(person?.信仰等级)) || number(person?.好感度) >= 60 || number(person?.堕落值) >= 60);
  const dossierOf = person => (person?.隐秘档案 && typeof person.隐秘档案 === 'object' ? person.隐秘档案 : null);

  // 写回变量：只有这一条路，AI 的补丁碰不到（守卫里把 隐秘档案 当脚本专属字段）。
  const saveDossier = async (id, dossier) => {
    await mutateCompanions(data => {
      const person = data.重要人物?.[id];
      if (!person) throw Error('人物已不存在');
      if (!canHaveDossier(fixedCharacter(id, person))) {
        // 男性或不符合条件的角色：拒绝保存，顺手清掉历史上残留的隐秘档案。
        delete person.隐秘档案;
        throw Error('隐秘档案只有成年女性核心/狂热信徒才有');
      }
      person.隐秘档案 = { ...dossier, 已生成: true };
    });
  };

  const chatMessages = () => {
    try {
      const context = hostWindow.SillyTavern?.getContext?.();
      return Array.isArray(context?.chat) ? context.chat.map(row => ({ is_user: !!row?.is_user, mes: String(row?.mes || '') })) : [];
    } catch { return []; }
  };

  const collectEvidence = (id, person) => {
    const api = dossierApi();
    const messages = chatMessages();
    const scenes = api.collectScenes(messages, text(person?.姓名) || id, 24);
    const evidence = { profile: { 姓名: person?.姓名, 年龄: person?.年龄, 身份: person?.身份, 外貌: person?.外貌, 性格: person?.性格, 背景: person?.背景, 信仰等级: person?.信仰等级, 近期经历: person?.近期经历 }, scenes };
    evidence.body = api.bodyEvidenceFromScenes(scenes, text(person?.姓名) || id);
    return evidence;
  };

  const generateDossier = async (id, person, options = {}) => {
    const api = dossierApi();
    const rank = api.RANKS.includes(options.rank) ? options.rank : api.rollRank();
    const evidence = collectEvidence(id, person);
    const messages = api.buildMessages({ character: evidence.profile, evidence, rank, existing: dossierOf(person) });
    const generate = hostWindow.TavernHelper?.generateRaw || hostWindow.generateRaw;
    if (typeof generate !== 'function') throw Error('当前酒馆助手不支持静默生成，请升级酒馆助手');
    // 模型偶尔会吐一段"差不多是 JSON"的文本：解析失败也算一次失败，带上纠正提示重试。
    const corrective = { role: 'user', content: '上一次输出不是合法 JSON。请只输出一个 JSON 对象：键和值都用英文双引号，不要尾逗号，值里不要换行、不要出现英文双引号，不要代码块，不要任何解释。' };
    let raw = '', parsed = null, lastError = null;
    for (let attempt = 0; attempt < 3 && !parsed; attempt++) {
      raw = '';
      try {
        raw = await generate({ ordered_prompts: attempt ? [...messages, corrective] : messages, should_silence: true, max_chat_history: 0 });
      } catch (error) { lastError = error; await new Promise(resolve => setTimeout(resolve, 800)); continue; }
      parsed = raw ? api.parseGenerated(raw) : null;
    }
    // 留一份原始返回，出问题时能在控制台直接看到模型到底写了什么。
    try { hostWindow.__xhcsLastDossierRaw = String(raw || ''); } catch { /* ignore */ }
    if (!raw) throw Error('生成失败：' + (lastError?.message || '模型没有返回内容'));
    if (!parsed) throw Error(`模型返回的不是合法 JSON（开头：${String(raw).replace(/\s+/g, ' ').slice(0, 60)}），请再生成一次`);
    const dossier = api.normalize(parsed, dossierOf(person), rank, evidence);
    await saveDossier(id, dossier);
    await refreshArchiveDossier(id);
    return dossier;
  };

  // 隐秘档案变了：只在这位人物已经有 [角色归档] 条目时才回写，不凭空造条目。
  const refreshArchiveDossier = async id => {
