  // 老虎机：48 步，间隔从 38ms 指数减速到 300ms，最后停在目标评级上。
  const startPussySlotMachine = (cell, id, person, targetRank, root) => {
    const api = dossierApi();
    const target = api.RANKS.includes(targetRank) ? targetRank : text(dossierOf(person)?.小穴评级) || api.RANKS[0];
    cell.replaceChildren();
    const spinner = createEl('span', 'xhcs-pussy-spin', api.RANKS[0]);
    cell.append(spinner);
    let step = 0;
    const total = 48 + Math.floor(Math.random() * 8);
    const tick = () => {
      step++;
      const index = step >= total ? api.RANKS.indexOf(target) : Math.floor(Math.random() * api.RANKS.length);
      const rank = api.RANKS[Math.max(0, index)];
      spinner.textContent = rank;
      spinner.className = `xhcs-pussy-spin xhcs-rarity-${api.rarityClass(rank)}`;
      if (step >= total) {
        spinner.className = `xhcs-pussy-rank xhcs-rarity-${api.rarityClass(target)}`;
        spinner.textContent = target;
        if (api.isMyth(target)) cell.closest('.xhcs-dossier')?.classList.add('xhcs-dossier-celebrate');
