          } catch (error) { hostWindow.toastr?.error?.(error.message, '香火成神系统'); }
        })();
        return;
      }
      const delay = 38 * Math.pow(300 / 38, step / total);
      hostWindow.setTimeout(tick, delay);
    };
    hostWindow.setTimeout(tick, 38);
  };

