    });reload.hidden=true;
    const check=companionButton('检查更新',async()=>{
      if(!runtime?.repository){version.textContent='请在酒馆中检查配套更新';return;}
      const installer=fullInstaller(),found=await installer.check(runtime.repository);
      pendingPackage=found.payload;const newer=installer.compare(found.version,runtime.version)>0;
