      const integrity=await installer.inspect(installed,found.payload,{...runtime,hudRevision:hostWindow.__xhcsHudV1?.revision,hudReady:hostWindow.__xhcsHudV1?.ready,panelRevision:hostDocument.querySelector('[data-xhcs-hud]')?.dataset.hudRevision});
