      const status = item.fits && item.reason ? `应急 · ${text(item.reason)}` : `今日可买 ${formatNumber(item.left)} 件`;
      const { node, actions } = shell(item, status);
      // 批量购买：可堆叠的消耗品才能选数量；权能卡、永久道具、限购 1 件的只能单买。
      const price = number(item.price) || 0;
      const balance = number(view?.balance) || 0;
      const maxAfford = price > 0 ? Math.floor(balance / price) : (number(item.left) || 1);
      const maxBuy = Math.max(1, Math.min(number(item.left) || 1, maxAfford));
      const canBatch = !item.power && !item.permanent && number(item.limit) > 1 && number(item.left) > 1 && price > 0 && maxBuy > 1;
      let qty = 1;
