        minus.onclick = event => { event.preventDefault(); event.stopPropagation(); setQty(qty - 1); };
        plus.onclick = event => { event.preventDefault(); event.stopPropagation(); setQty(qty + 1); };
        maxBtn.onclick = event => { event.preventDefault(); event.stopPropagation(); setQty(maxBuy); };
        stepper.append(minus, value, plus, maxBtn);
        actions.append(stepper);
      }
      buy.onclick = async event => {
        event.preventDefault(); event.stopPropagation();
        if (!item.canBuy) return;
        const total = price * qty;
        const message = qty > 1
          ? `确认花费 ${formatNumber(total)} 点神力，批量购买「${text(item.name)} × ${qty}」？买后一起放进背包。确认前不会扣费。`
          : `确认花费 ${formatNumber(price)} 点神力购买「${text(item.name)}」？买后放进背包，用的时候才生效。确认前不会扣费。`;
        const ok = await confirmCompanionAction({ title: qty > 1 ? '批量购买' : '购买物品', message, label: qty > 1 ? `确认购买 ×${qty}` : '确认购买', root, opener: buy, kind: 'purchase' });
