    if (shelf === 'cross') body.append(createEl('p', 'xhcs-shop-note', '跨界货架每个剧情日换一次。界外的东西在这个世界没人见过。'));
    if (view?.__unavailable) {
      grid.append(createEl('p', 'xhcs-empty', view.__error || '本系统数据暂不可用'));
    } else if (shelf === 'today') {
      const goods = store.goods || [];
      if (!goods.length) grid.append(createEl('p', 'xhcs-empty', '货架暂时是空的。'));
      goods.forEach(item => grid.append(buyCard(item)));
    } else if (shelf === 'cross') {
      const items = store.cross || [];
      if (!items.length) grid.append(createEl('p', 'xhcs-empty', '还没定下当前世界，跨界货架不开。'));
      for (const world of [...new Set(items.map(item => item.from))]) {
        const group = createEl('div', 'xhcs-shop-group');
        group.append(createEl('h5', 'xhcs-shop-subtitle', `来自${world}`));
        const inner = createEl('div', 'xhcs-shop-grid');
        items.filter(item => item.from === world).forEach(item => inner.append(buyCard(item)));
        group.append(inner); grid.append(group);
      }
    } else if (shelf === 'lewd') {
      if (!store.lewdOn) grid.append(createEl('p', 'xhcs-empty', '祈愿簿里关掉了涩的内容，这里也不上架。'));
      else (store.lewd || []).forEach(item => grid.append(buyCard(item)));
    } else {
      const followers = store.followers || [];
      if (!followers.length) grid.append(createEl('p', 'xhcs-empty', '还没有核心信徒。信徒的信仰度到 60 会升为核心。'));
      for (const item of store.followerPowers || []) {
        const { node, actions } = shell({ ...item, kind: '神赐' }, item.canBuy ? (item.uses ? `可用 ${item.uses} 次` : '常驻') : text(item.why));
        if (followers.length) {
          const picker = createEl('select', 'xhcs-shop-target');
          picker.setAttribute('aria-label', `把${text(item.name)}赐给谁`);
          const none = createEl('option', '', '赐给谁'); none.value = ''; picker.append(none);
          for (const person of followers) {
            const option = createEl('option', '', `${person.name}（${person.level} · ${person.used}/${person.slots}）`);
            option.value = person.id; option.disabled = person.used >= person.slots; picker.append(option);
          }
          picker.addEventListener('click', event => event.stopPropagation());
          const grant = createEl('button', 'xhcs-companion-button xhcs-shop-btn xhcs-shop-btn-permanent', `赐予 · ${formatNumber(item.price)}点`);
          grant.type = 'button';
          if (!item.canBuy) { grant.disabled = true; grant.title = text(item.why); }
          grant.onclick = async event => {
            event.preventDefault(); event.stopPropagation();
            if (!item.canBuy) return;
            const target = picker.value;
            if (!target) { alert.textContent = '先选一个人'; alert.hidden = false; return; }
            const who = followers.find(person => person.id === target);
            const ok = await confirmCompanionAction({ title: '赐予权能', message: `确认花费 ${formatNumber(item.price)} 点神力，把「${text(item.name)}」赐给${who?.name || target}？下一轮正文会写她得到这份力量。`, label: '确认赐予', root, opener: grant, kind: 'purchase' });
            if (ok) run('grantPower', { id: item.id, target }, grant);
          };
          actions.append(picker, grant);
        }
        grid.append(node);
      }
    }
    body.append(grid, alert);
  };

  const showShopDialog = (root, opener) => {
    hostDocument.querySelectorAll('[data-shop-dialog]').forEach(dialog => dialog.close());
    const { dialog, open } = themedCompanionDialog('系统商城', root, opener);
    dialog.dataset.shopDialog = '';
    let shelf = 'today';
    const body = createEl('div', 'xhcs-shop-dialog-body');
    dialog.append(body);
    const latest = () => hostWindow.Mvu?.getMvuData?.({ type: 'message', message_id: latestAssistantMessage()?.message_id })?.stat_data;
    dialog.refresh = () => {
      const data = latest();
      const view = data ? gameView(data) : { __unavailable: true, __error: '本系统数据暂不可用' };
      renderShopDialogBody(body, root, view, shelf, next => { shelf = next; dialog.refresh(); }, () => dialog.refresh());
    };
    dialog.refresh(); open();
  };

  const renderBag = (mount, root, view) => {
    if (view?.__unavailable) {
      const box = createEl('details', 'xhcs-bag'); box.dataset.key = 'bag'; box.open = true;
      box.append(createEl('summary', 'xhcs-bag-summary', '背包'), createEl('p', 'xhcs-empty', view.__error || '本系统数据暂不可用'));
      mount.append(box); return;
    }
    const store = view?.store || {};
    const pending = store.pending || [], evolving = store.evolving || [], bag = store.bag || [];
    const present = store.present || [];
    const box = createEl('details', 'xhcs-bag'); box.dataset.key = 'bag'; box.open = true;
    box.append(createEl('summary', 'xhcs-bag-summary', `背包 · ${formatNumber(bag.length)} 件${pending.length ? ` · ${pending.length} 件等待生效` : ''}`));
    const run = async (kind, payload, button) => {
      if (button) button.disabled = true;
      try {
        const api = gameApi();
        if (!api || typeof api.action !== 'function') throw new Error('本系统数据暂不可用');
        await api.action(kind, { ...payload, expectedContext: text(view?.contextToken) });
        state.signature = ''; scheduleRender(0, false);
      } catch (err) { hostWindow.toastr?.error?.(err?.message || String(err), '香火成神系统'); }
      finally { if (button) button.disabled = false; }
    };

    if (pending.length) {
      box.append(createEl('h5', 'xhcs-shop-subtitle', '等待生效'));
      const grid = createEl('div', 'xhcs-shop-grid');
      for (const item of pending) {
        const card = createEl('article', 'xhcs-shop-card'); card.dataset.state = 'active';
        const top = createEl('div', 'xhcs-shop-card-head'), title = createEl('div', 'xhcs-shop-card-title');
        title.append(createEl('strong', 'xhcs-power-name', text(item.name)));
        top.append(title, createEl('span', 'xhcs-shop-status', item.kind === '权能卡' ? '可随时发动' : '下一轮回复生效'));
        card.append(top);
        if (item.target) card.append(createEl('p', 'xhcs-power-desc', `用在：${item.target}`));
        const actions = createEl('div', 'xhcs-shop-actions');
        const undo = createEl('button', 'xhcs-companion-button xhcs-shop-btn', '撤回'); undo.type = 'button';
        undo.onclick = event => { event.preventDefault(); event.stopPropagation(); run('cancelGood', { instance: item.instance }, undo); };
        actions.append(undo); card.append(actions); grid.append(card);
      }
      box.append(grid);
    }

    if (evolving.length) {
      box.append(createEl('h5', 'xhcs-shop-subtitle', '神力演化中'));
      const grid = createEl('div', 'xhcs-shop-grid');
      for (const item of evolving) {
        const card = createEl('article', 'xhcs-shop-card'); card.dataset.state = 'active';
        const top = createEl('div', 'xhcs-shop-card-head'), title = createEl('div', 'xhcs-shop-card-title');
        title.append(createEl('strong', 'xhcs-power-name', text(item.name)));
        top.append(title, createEl('span', 'xhcs-shop-status', item.permanent ? '穿戴中 · 永久' : `余 ${formatDurationText(item.remaining)}`));
        card.append(top);
        if (item.target) card.append(createEl('p', 'xhcs-power-desc', `在${text(item.target)}那里`));
        const actions = createEl('div', 'xhcs-shop-actions');
        for (const line of ['轻一点', '加大', '换个花样']) {
          const button = createEl('button', 'xhcs-companion-button xhcs-shop-btn', line); button.type = 'button';
          button.onclick = event => { event.preventDefault(); event.stopPropagation(); fillInput(`（${text(item.name)}）${line}一档。`); };
          actions.append(button);
        }
        if (item.goodId === 'lewd_toylink' || /遥控|遥感|共鸣/.test(text(item.name))) {
          const remote = createEl('button', 'xhcs-companion-button xhcs-shop-btn xhcs-shop-btn-permanent', '打开遥控器');
          remote.type = 'button'; remote.dataset.openToylink = item.instance;
          remote.onclick = event => {
            event.preventDefault(); event.stopPropagation();
            try { openToylink(item); } catch (error) { hostWindow.toastr?.error?.(error.message, '香火成神系统'); }
          };
          actions.append(remote);
        }
        const stop = createEl('button', 'xhcs-companion-button xhcs-shop-btn xhcs-shop-btn-temporary', '收回'); stop.type = 'button';
        stop.onclick = async event => {
          event.preventDefault(); event.stopPropagation();
          const ok = await confirmCompanionAction({ title: '收回演化', message: `确认收回「${text(item.name)}」？它会立刻化回神力散去。`, label: '确认收回', root, opener: stop, kind: 'delete' });
          if (ok) run('endEvolve', { instance: item.instance }, stop);
        };
        actions.append(stop); card.append(actions); grid.append(card);
      }
      box.append(grid);
    }

    const paint = () => {
      box.querySelectorAll('.xhcs-bag-filter,.xhcs-bag-grid,.xhcs-bag-cap,.xhcs-bag-empty').forEach(node => node.remove());
      const filter = createEl('div', 'xhcs-bag-filter');
      for (const name of ['全部', '商城', '供奉', '化身所得']) {
        const button = createEl('button', '', name); button.type = 'button';
        button.setAttribute('aria-pressed', String(state.bagFilter === name));
        button.onclick = event => { event.preventDefault(); event.stopPropagation(); state.bagFilter = name; paint(); };
        filter.append(button);
      }
      box.append(filter);
      const shown = state.bagFilter === '全部' ? bag : bag.filter(item => item.source === state.bagFilter);
      if (!shown.length) {
        box.append(createEl('p', 'xhcs-empty xhcs-bag-empty', bag.length ? '这一类里没有东西。' : '背包是空的。商城买的、信徒供奉的、化身得到的东西都会放在这里。'));
        box.append(createEl('p', 'xhcs-bag-cap', `${formatNumber(bag.length)} / ${formatNumber(store.bagMax ?? 48)} 格`));
        return;
      }
      const grid = createEl('div', 'xhcs-shop-grid xhcs-bag-grid');
      for (const item of shown) {
        const card = createEl('article', 'xhcs-shop-card');
        const top = createEl('div', 'xhcs-shop-card-head'), title = createEl('div', 'xhcs-shop-card-title');
        title.append(createEl('strong', 'xhcs-power-name', text(item.name)));
        const from = item.source === '供奉' ? `供奉${item.from ? ` · ${text(item.from)}` : ''}` : item.category === '界外' ? `界外${item.from ? ` · ${text(item.from)}` : ''}` : text(item.source);
        const badge = createEl('span', 'xhcs-shop-stage-badge', from);
        if (item.category === '界外') badge.dataset.kind = '界外';
        title.append(badge);
        top.append(title, createEl('span', 'xhcs-shop-status', item.permanent ? '永久持有' : `× ${formatNumber(item.count)}`));
        card.append(top, createEl('p', 'xhcs-power-desc', text(item.desc)));
        const actions = createEl('div', 'xhcs-shop-actions');
        let picker = null;
        if (item.needsTarget && present.length) {
          picker = createEl('select', 'xhcs-shop-target');
          picker.setAttribute('aria-label', `${text(item.name)}用在谁身上`);
          const fanaticOnly = item.targetType === 'fanatic';
          // 0.24.0：遥控套装只给在场的成年女性，且需【狂热】或堕落值 ≥80。
          const eligible = person => fanaticOnly
            ? (isAdultFemalePerson(person) && (person.level === '狂热' || number(person.堕落值) >= 80))
            : true;
          const options = present.filter(eligible);
          if (fanaticOnly && !options.length) {
            const none = createEl('option', '', '需有狂热或堕落≥80的女性在场'); none.value = ''; picker.append(none);
            picker.disabled = true;
          } else {
            const none = createEl('option', '', item.targetType === 'self' ? 'USER 自己' : fanaticOnly ? '选一位狂热/沉沦女性' : '不指定');
            none.value = ''; picker.append(none);
            for (const person of options) {
              const tag = fanaticOnly ? (person.level === '狂热' ? '（狂热）' : '（沉沦）') : '';
              const option = createEl('option', '', `${text(person.name)}${tag}`); option.value = person.id; picker.append(option);
            }
          }
          picker.addEventListener('click', event => event.stopPropagation());
          actions.append(picker);
        }
        const use = createEl('button', 'xhcs-companion-button xhcs-shop-btn xhcs-shop-btn-temporary', '使用'); use.type = 'button';
        if (item.targetType === 'fanatic' && !present.some(person => isAdultFemalePerson(person) && (person.level === '狂热' || number(person.堕落值) >= 80))) { use.disabled = true; use.title = '仅限对在场成年女性（狂热或堕落≥80）使用'; }
        use.onclick = async event => {
          event.preventDefault(); event.stopPropagation();
          const target = picker?.value || '';
          const ok = await confirmCompanionAction({ title: '使用物品', message: `确认使用「${text(item.name)}」？下一轮回复时生效，生效前可以撤回。`, label: '确认使用', root, opener: use, kind: 'purchase' });
          if (ok) {
            const who = target ? ` → ${text(present.find(person => person.id === target)?.name || '')}` : '';
            const cue = `（使用道具：${text(item.name)}${who}）`;
            run('useGood', { id: item.id, target }, use).then(() => {
              fillInput(cue);
              hostWindow.toastr?.info?.(`已激活「${text(item.name)}」并同步至输入框，发送消息即可在下一楼正文生效`, '香火成神系统');
            });
          }
        };
        actions.append(use);
        // 永久道具（遥控套装）不提供丢弃。
        if (!item.permanent) {
          const drop = createEl('button', 'xhcs-companion-button xhcs-shop-btn', '丢弃'); drop.type = 'button';
          drop.onclick = async event => {
            event.preventDefault(); event.stopPropagation();
            const ok = await confirmCompanionAction({ title: '丢弃物品', message: `确认丢掉「${text(item.name)}」×${formatNumber(item.count)}？丢了就找不回来了。`, label: '确认丢弃', root, opener: drop, kind: 'delete' });
            if (ok) run('dropGood', { id: item.id }, drop);
          };
          actions.append(drop);
        }
        card.append(actions);
        grid.append(card);
      }
      box.append(grid, createEl('p', 'xhcs-bag-cap', `${formatNumber(bag.length)} / ${formatNumber(store.bagMax ?? 48)} 格`));
    };
    paint();
    mount.append(box);
  };

  // 遥控套装：把目标与实例交给 TOY-LINK，再开面板。
  const openToylink = item => {
    const api = hostWindow.__TOYLINK__;
    if (!api) throw Error('遥控器模块还没就绪，请刷新页面');
    api.setTarget?.({ id: item.targetId || '', name: item.target || '', instance: item.instance });
    api.open?.();
  };

  let toylinkOpenedFor = '';
  // 遥控套装的生命周期跟着「神力演化中」走：有就绑定目标（并自动弹一次面板），没有就停。
  const syncToylink = view => {
    const api = hostWindow.__TOYLINK__;
    if (!api) return;
    const toy = (view?.store?.evolving || []).find(row => row.goodId === 'lewd_toylink');
    if (!toy) { toylinkOpenedFor = ''; api.stop?.(); return; }
    api.setTarget?.({ id: toy.targetId || '', name: toy.target || '', instance: toy.instance });
    if (toylinkOpenedFor !== toy.instance) { toylinkOpenedFor = toy.instance; setTimeout(() => { try { api.open?.(); } catch (error) { console.warn('[香火成神] 遥控器打开失败', error); } }, 400); }
  };

  // 「己身」最上方：肉身与神像的能力/力量状态（领域内碾压阶梯 + 域外肉身境界）。
  const renderSelfPower = (mount, view) => {
    const sp = view?.selfPower;
    if (!sp) return;
    const box = createEl('details', 'xhcs-bag xhcs-self-power');
    box.dataset.key = 'self-power'; box.open = true;
    box.append(createEl('summary', 'xhcs-bag-summary', `肉身与神像 · ${text(sp.stageName)}`));
    box.append(createEl('p', 'xhcs-power-desc', `【领域不死铁律】${text(sp.immortalityRule)}`));
    const group = (title, lines) => {
      const section = createEl('section', 'xhcs-power-section');
      section.append(createEl('h5', 'xhcs-shop-subtitle', title));
      for (const [label, value] of lines) {
        if (!text(value)) continue;
        const row = createEl('div', 'xhcs-context-row');
        row.append(createEl('b', '', label), createEl('span', '', text(value)));
        section.append(row);
      }
      box.append(section);
      return section;
    };
    group('神像本体（及领域内化身）战力对标', [
      ['神像阶段', sp.stageName],
      ['内圈·绝对无敌领域', sp.invincibleRadius],
      ['外圈·神力领域范围', sp.powerRadius],
      ['双重领域合计', sp.domainRadius],
      ['无敌法则', sp.invincibleRule],
      ['当前世界', sp.world],
      ['领域内', sp.statueBenchmark],
    ]);
    group('肉身 / 化身能力状态', [
      ['肉身位格', sp.bodyTitle],
      ['当前状态', `${sp.avatarState} · 位于${sp.avatarLoc}`],
      ['领域内实力', sp.bodyInDomain],
      ['领域外实力', sp.bodyOutDomain],
    ]);
    if (Array.isArray(sp.ladder) && sp.ladder.length) {
      const ladder = createEl('details', 'xhcs-self-ladder');
      ladder.append(createEl('summary', 'xhcs-bag-summary', '完整境界对照 · 泥像期 → 玉像期'));
      for (const row of sp.ladder) {
        const line = createEl('div', 'xhcs-context-row');
        line.dataset.current = row.current ? 'true' : 'false';
        line.append(createEl('b', '', `${row.stage} · 无敌 ${row.invincibleRadius || row.radius} / 神力 ${row.powerRadius || '—'}`), createEl('span', '', `${row.invincibleRule ? `${row.invincibleRule}｜` : ''}神像：${row.statue}｜肉身出域：${row.bodyOut}`));
        ladder.append(line);
      }
      box.append(ladder);
