  const renderSelf = (root, data) => {
    const view = gameView(data);
    const power = root.querySelector('[data-role="self-power"]');
    const shop = root.querySelector('[data-role="self-shop"]'), bag = root.querySelector('[data-role="self-bag"]');
    const wishes = root.querySelector('[data-role="self-wishes"]'), ledger = root.querySelector('[data-role="self-ledger"]');
    if (!shop || !bag || !wishes || !ledger) return;
    power?.replaceChildren();
    shop.replaceChildren(); bag.replaceChildren(); wishes.replaceChildren(); ledger.replaceChildren();
    if (power) renderSelfPower(power, view);
    renderPowerShop(shop, root, view);
    renderBag(bag, root, view);
    renderWishBook(wishes, root, data);
    renderLedger(ledger, view);
    syncToylink(view);
    const tab = root.querySelector('[data-tab="self"]');
    if (!tab) return;
    const waiting = view.__unavailable ? 0 : (view.wishes?.items || []).filter(item => !item.choice).length;
    tab.dataset.badge = waiting ? String(waiting) : '';
    tab.setAttribute('aria-label', waiting ? `己身，${waiting} 个祈愿待处理` : '己身');
  };

  const renderPromotionControls = (root, data, view) => {
    const box = root.querySelector('.xhcs-progress-box');
    if (!box) return;
    const promo = view?.__unavailable ? nextPromotion(data) : (view?.promotion || nextPromotion(data));
    setRoleText(root, 'promotion-title', text(promo.label) || '神格晋升');
    setRoleText(root, 'promotion-copy', text(promo.detail));

    const fill = root.querySelector('[data-role="promotion-fill"]');
    if (fill) {
      const percent = Math.round(number(promo.progress) * 100);
      const valid = !view?.__unavailable && Number.isFinite(percent);
      fill.style.setProperty('--xhcs-progress', `${valid ? Math.max(0, Math.min(100, percent)) : 0}%`);
      fill.parentElement.hidden = !valid;
      fill.parentElement.setAttribute('aria-valuenow', String(valid ? Math.max(0, Math.min(100, percent)) : 0));
      fill.parentElement.setAttribute('aria-valuetext', text(promo.detail) || text(promo.label));
    }

    let extra = box.querySelector('[data-role="promotion-extra"]');
    if (!extra) {
      extra = createEl('div', 'xhcs-promotion-extra');
      extra.dataset.role = 'promotion-extra';
      box.append(extra);
    }
    extra.replaceChildren();

    if (view?.__unavailable) {
      extra.hidden = true;
      return;
    }

    const pending = data?.神格?.待演晋升 || view?.pendingPromotion;
    if (pending && text(pending.到)) {
      const badge = createEl('div', 'xhcs-promotion-meta');
      badge.append(createEl('span', 'xhcs-promotion-reason', `⏳ 待演出：${text(pending.从) || '当前阶段'}→${text(pending.到)}，下一次发言时演出`));
      extra.append(badge);
      extra.hidden = false;
    }

    const reqs = Array.isArray(promo.requirements) ? promo.requirements : [];
    if (reqs.length) {
      const reqList = createEl('div', 'xhcs-promotion-reqs');
      reqs.forEach(req => {
        const pill = createEl('div', 'xhcs-promotion-req');
        pill.dataset.met = req.met ? 'true' : 'false';
        const cur = Number.isFinite(number(req.current)) ? formatNumber(req.current) : text(req.current);
        const tgt = Number.isFinite(number(req.target)) ? formatNumber(req.target) : text(req.target);
        pill.append(
          createEl('span', 'xhcs-promotion-req-label', text(req.label)),
          createEl('strong', 'xhcs-promotion-req-val', `${cur}/${tgt}`)
        );
        reqList.append(pill);
      });
      extra.append(reqList);
    }

    const isMaxOrHidden = promo.locked || !promo.to || /宇宙/.test(text(promo.to)) || /最高阶段/.test(text(promo.label)) || text(view?.stage || data?.神格?.神像阶段) === '玉像期';
    if (isMaxOrHidden) {
      extra.hidden = !extra.childNodes.length;
      return;
    }

    extra.hidden = false;
    const footer = createEl('div', 'xhcs-promotion-footer');
    const metaInfo = createEl('div', 'xhcs-promotion-meta');
    const costVal = number(promo.cost);
    if (Number.isFinite(costVal) && costVal >= 0) {
      metaInfo.append(createEl('span', 'xhcs-promotion-cost', `晋升消耗：${formatNumber(costVal)} 点神力`));
    }
    const statusNote = text(promo.reason) || (promo.eligible ? '各项条件齐备，可凝聚更高神格' : '条件尚未圆满');
