      btn.disabled = true;
      btn.dataset.busy = 'true';
      const prevText = btn.textContent;
      btn.textContent = '神格凝聚中…';
      try {
        const api = gameApi();
        if (!api || typeof api.action !== 'function') throw new Error('本系统数据暂不可用');
