  const displayClock = data => {
    const t=data?.时序;
    if(!t?.已初始化)return '历时待校准';
    const base=Date.parse(String(t.起始时刻).replace(' ','T')+':00Z');
    if(!Number.isFinite(base)||!Number.isSafeInteger(t.经过分钟))return '历时待校准';
    const d=new Date(base+t.经过分钟*60000),p=n=>String(n).padStart(2,'0');
    return `${CALENDARS[data?.世界?.当前世界]||''}${d.getUTCFullYear()}年${p(d.getUTCMonth()+1)}月${p(d.getUTCDate())}日 ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
