        <div class="xhcs-progress-track" role="progressbar" aria-label="晋升数量条件" aria-valuemin="0" aria-valuemax="100"><div class="xhcs-progress-fill" data-role="promotion-fill"></div></div>
        <div class="xhcs-progress-copy" data-role="promotion-copy"></div>
      </div><div class="xhcs-hud-archive" data-role="memories"></div>
    </div><div data-view="map" role="tabpanel" tabindex="0" hidden><div data-role="map"></div></div>
  `;

  const bindNavigation = (panel, messageId) => {
    const update=panel.querySelector('[data-xhcs-update]');
    update.onclick=()=>showCompanionSettings(panel,update);
    const tabs = [...panel.querySelectorAll('[data-tab]')];
    const activate = tab => {
      tabs.forEach(button => { const selected = button === tab; button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; });
      panel.querySelectorAll('[data-view]').forEach(view => { view.hidden = view.dataset.view !== tab.dataset.tab; });
    };
    tabs.forEach((button, index) => {
      const view = panel.querySelector(`[data-view="${button.dataset.tab}"]`);
      button.id = `xhcs-tab-${messageId}-${button.dataset.tab}`;
      view.id = `xhcs-view-${messageId}-${button.dataset.tab}`;
      button.setAttribute('aria-controls', view.id); view.setAttribute('aria-labelledby', button.id);
      button.addEventListener('click', () => activate(button));
      button.addEventListener('keydown', event => {
        const keys = { ArrowRight:(index + 1) % tabs.length, ArrowLeft:(index + tabs.length - 1) % tabs.length, Home:0, End:tabs.length - 1 };
        if (!(event.key in keys)) return;
        event.preventDefault(); const next = tabs[keys[event.key]]; activate(next); next.focus();
      });
    });
  };

  const renderContext = (root, role, fields) => {
    const target = root.querySelector(`[data-role="${role}"]`);
    target.replaceChildren();
    fields.forEach(([label, value]) => {
      if (!text(value) || text(value) === '未确认') return;
      const row = createEl('div', 'xhcs-context-row'); row.append(createEl('b', '', label), createEl('span', '', text(value))); target.append(row);
    });
  };

  const setRoleText = (root, role, value) => {
    const node = root.querySelector(`[data-role="${role}"]`);
    if (node) node.textContent = text(value);
  };

  const renderPerson = (id, person) => {
    const box=createEl('article','xhcs-person xhcs-person-compact');box.dataset.key=`person:${id}`;
    const head=createEl('div','xhcs-person-head');
    head.append(avatarButton(person,id,box,true),createEl('strong','xhcs-person-name',text(person?.姓名)||id));
    if(text(person?.信仰等级)&&person.信仰等级!=='未确认')head.append(createEl('span','xhcs-faith-badge',person.信仰等级));
    const fresh=promotionBadgeFor(id);
    if(fresh)head.append(createEl('span','xhcs-devotion-new',fresh));
    box.append(head);
    const devotion=devotionRow(id,person);
    if(devotion)box.append(devotion);
    return box;
  };

  // 成年女性判定（与 clock.js 的 isAdultFemale 同一套口径）。
  const isAdultFemalePerson = person => {
    if (!person || typeof person !== 'object') return false;
    if (Number.isFinite(Number(person.年龄)) && Number(person.年龄) < 18) return false;
    const g = text(person.性别);
    return Boolean(g && !g.includes('男') && (g.includes('女') || g.includes('雌') || g.includes('母')));
  };
  const affectionStageLabel = value => {
    const rows = gameApi()?.catalog?.affection?.stages || [];
    let label = rows[0]?.label || '陌路';
    for (const row of rows) if (value >= number(row.min)) label = row.label;
    return label;
  };
  const corruptionStageOf = value => {
    const rows = gameApi()?.catalog?.corruption?.stages || [];
    let row = rows[0] || { label: '清白', cue: '' };
    for (const item of rows) if (value >= number(item.min)) row = item;
    return row;
  };
  // 三维仪表盘：信仰度（鎏金，仅信徒）/ 好感度（绯粉，所有人）/ 堕落值（魅紫，仅成年女性）。
  const renderPersonMeters = (id, person, mode = 'card') => {
    const stored = data_current?.重要人物?.[id] || person;
    const level = text(stored?.信仰等级);
    const believer = ['普通', '核心', '狂热'].includes(level);
    const female = isAdultFemalePerson(stored);
    const detail = mode === 'detail';
    const aff = number(stored?.好感度);
    const cor = number(stored?.堕落值);
    if (!believer && !Number.isFinite(aff) && !female) return null;
    const box = createEl('div', detail ? 'xhcs-profile-meters-card' : 'xhcs-card-meters');
    const row = (kind, name, value, cap, suffix) => {
      if (!Number.isFinite(value) && kind !== 'faith') return null;
      const wrap = createEl('div', `xhcs-meter is-${kind}`);
      const top = createEl('div', 'xhcs-meter-top');
      top.append(createEl('span', 'xhcs-meter-name', name), createEl('span', 'xhcs-meter-badge', suffix));
      const bar = createEl('progress', 'xhcs-meter-bar');
      bar.max = cap;
      bar.value = Math.max(0, Math.min(Number.isFinite(value) ? value : 0, cap));
      bar.setAttribute('aria-label', `${text(stored?.姓名) || id}的${name}`);
      wrap.append(top, bar);
      box.append(wrap);
      return wrap;
    };
    if (believer) {
      if (level === '狂热') row('faith', '信仰', 100, 100, 'MAX · 狂热');
      else {
        const cap = level === '核心' ? 100 : 60;
        const raw = Number.isFinite(number(stored?.信仰度)) ? number(stored.信仰度) : number(gameApi()?.catalog?.devotion?.legacy?.[level]);
        const boost = aff >= 80 ? ' · 好感加持 +50%' : aff >= 60 ? ' · 好感加持 +25%' : '';
        row('faith', '信仰', raw, cap, `${formatNumber(raw)} / ${cap}${detail ? boost : ''}`);
      }
    }
    if (Number.isFinite(aff)) row('affection', '好感', aff, 100, `${formatNumber(aff)} / 100 · ${affectionStageLabel(aff)}`);
    if (female) {
      const stage = corruptionStageOf(Number.isFinite(cor) ? cor : 0);
      row('corruption', '堕落', Number.isFinite(cor) ? cor : 0, 100, `${formatNumber(Number.isFinite(cor) ? cor : 0)} / 100 · ${stage.label}`);
      if (detail && stage.cue) box.append(createEl('p', 'xhcs-meter-cue', stage.cue));
      if (detail && aff >= 60 && !believer) box.append(createEl('p', 'xhcs-meter-cue', '【高好感易入信】好感 ≥60 时入信，初始信仰直接带上好感折算。'));
