    return box;
  };
  // 旧调用点保留一个薄封装：只画信仰那一行。
  const devotionRow = (id, person) => {
    const stored = data_current?.重要人物?.[id] || person;
    const level = text(stored?.信仰等级);
    if (!['普通', '核心', '狂热'].includes(level)) return null;
    const meters = renderPersonMeters(id, person, 'card');
    return meters;
  };
  // 旧实现（保留注释以说明历史口径）：信仰度条：普通 / 60、核心 / 100、狂热 MAX。
  const devotionRowLegacy = (id, person) => {
    // 只认变量里已经结算过的值：资料版本里不该有这三个字段，旧版本残留的不能露出来。
    const stored = data_current?.重要人物?.[id] || person;
    const level = text(stored?.信仰等级);
    if (!['普通', '核心', '狂热'].includes(level)) return null;
    const catalog = gameApi()?.catalog;
    const raw = number(stored?.信仰度);
    // 刚迁移完、还没走过一轮结算的旧档没有信仰度：按脚本的 legacy 表显示，结算后就是同一个值。
    const fallback = number(catalog?.devotion?.legacy?.[level]);
    const value = Number.isFinite(raw) ? raw : Number.isFinite(fallback) ? fallback : 0;
    const box = createEl('div', 'xhcs-devotion');
    if (level === '狂热') {
      box.dataset.max = 'true';
      box.append(createEl('span', '', '信仰 MAX'));
      return box;
    }
    const cap = level === '核心' ? 100 : 60;
    const rank = number((catalog?.stages || []).find(row => row.stage === text(data_current?.神格?.神像阶段))?.rank);
    const blocked = level === '核心' && value >= 99 && rank < number(catalog?.devotion?.fanaticMinRank ?? 1);
    box.append(createEl('span', '', blocked ? `信仰 ${formatNumber(value)} · 狂热需石像期` : `信仰 ${formatNumber(value)} / ${cap}`));
    const progress = createEl('progress', 'xhcs-task-progress');
    progress.max = cap;
    progress.value = Math.max(0, Math.min(value, cap));
    progress.setAttribute('aria-label', `${text(person?.姓名) || id}的信仰度`);
    box.append(progress);
    return box;
  };

  const promotionBadgeFor = id => {
    const rows = Array.isArray(data_current?.信徒培养?.待演升级) ? data_current.信徒培养.待演升级 : [];
    const row = rows.find(item => item.人物ID === id);
    return row ? `刚升为${text(row.到)}` : '';
