    const powers = Array.isArray(view.powers) ? [...view.powers] : [];
    const catalogPowers = Array.isArray(gameApi()?.catalog?.powers) ? gameApi().catalog.powers : [];
    const declared = new Set(
      Array.isArray(data?.神格?.已解锁能力) ? data.神格.已解锁能力.map(text) : [],
    );
    declared.forEach(name => {
      if (!name || name === '精神共鸣') return;
      if (!powers.some(p => text(p.name) === name) && !catalogPowers.some(p => text(p.name) === name)) {
        powers.push({ name, cost: '未记录', description: '该权柄由当前卡状态解锁，消耗以世界书规则为准。', temporary: false });
