  };

  const renderWishBook=(target,root,data)=>{
    const view=gameView(data),book=view?.wishes;
    if(view?.__unavailable||!book)return;
    const open=book.items.filter(x=>!x.choice).length;
    const box=createEl('details','xhcs-wish-book');box.dataset.key='wish-book';box.open=open>0;
    box.append(createEl('summary','xhcs-wish-summary',open?`祈愿簿 · 今天还有 ${open} 个人在等`:'祈愿簿 · 今天都处理完了'));
    const alert=createEl('p','xhcs-review-alert');alert.hidden=true;
    const act=async(kind,payload,button)=>{
      if(button)button.disabled=true;
      try{await gameApi().action(kind,{...payload,expectedContext:text(view.contextToken)});state.signature='';scheduleRender(0,false);return true;}
      catch(error){alert.textContent=error?.message||String(error);alert.hidden=false;if(button)button.disabled=false;return false;}
    };
    book.items.forEach(item=>{
      const card=createEl('article','xhcs-wish-card');card.dataset.kind=text(item.kind);if(item.choice)card.dataset.done='';
      const who=createEl('strong','xhcs-wish-who',text(item.who));
      const line=createEl('p','xhcs-wish-text',text(item.text));
      card.append(who,line);
      if(item.choice)card.append(createEl('p','xhcs-wish-state',`你${text(item.choice)}了`));
      else{
        const actions=createEl('div','xhcs-wish-actions');
        for(const choice of ['应了','捉弄','不理']){
          const b=createEl('button','xhcs-companion-button',choice);b.type='button';
          b.onclick=async event=>{
            event.preventDefault();event.stopPropagation();
            const ok=await act('wish',{instance:item.instance,choice},b);
            if(ok&&choice!=='不理'){
              const input=hostDocument.querySelector('#send_textarea');
              if(input&&!input.value.trim()){input.value=`（祈愿簿）${choice==='应了'?'我应了':'我决定捉弄'}${text(item.who)}。`;input.dispatchEvent(new hostWindow.Event('input',{bubbles:true}));input.focus();}
            }
          };
          actions.append(b);
        }
        card.append(actions);
      }
      box.append(card);
    });
    // 涩内容与随机来客的设置已经搬进状态栏「设置」，这里只留祈愿本身。
    box.append(alert);
    target.append(box);
