  const renderLedger=(mount,view)=>{
    const ledger=view?.ledger;if(!ledger)return;
    const box=createEl('details','xhcs-ledger');box.dataset.key='power-ledger';
    box.append(createEl('summary','xhcs-ledger-summary',`神力账本 · 收入 ${formatNumber(ledger.income)} · 支出 ${formatNumber(ledger.expense)}`));
