    const addPart=(label,value,sign)=>{const row=createEl('div','xhcs-ledger-part');row.append(createEl('dt','',label),createEl('dd','',`${value>0?sign:''}${formatNumber(value)}`));parts.append(row);};
    addPart('起始',ledger.base,'');
